## Exercise 3 — a compound component

Edit `ex3/solution.tsx`. Build `Tabs` as a parent plus three sub-components
that find it through a private context.

Export:

```tsx
export function Tabs(props: {
  defaultValue: string;
  children: ReactNode;
}): ReactElement;
export function TabList(props: { children: ReactNode }): ReactElement;
export function Tab(props: { value: string; children: ReactNode }): ReactElement;
export function TabPanel(props: { value: string; children: ReactNode }): ReactElement;
```

Behaviour:

- `Tabs` owns the selected value, starting at `defaultValue`;
- `TabList` renders a `<div role="tablist">` around its children;
- `Tab` renders a `<button type="button" role="tab">` whose `aria-selected` is
  `true` only for the selected value; clicking it selects that value;
- `TabPanel` renders a `<div role="tabpanel">` with its children **only** when
  its value is selected, and renders nothing otherwise;
- `TabList`, `Tab` or `TabPanel` used outside a `Tabs` must throw an `Error`
  whose message contains both the offending component's name and `Tabs` — for
  example `<Tab> must be rendered inside <Tabs>`.

Do **not** export the context object. The gate imports every named export and
fails if a context leaks out.

```
uv run dojo test react v3rc01_component_api_design ex3
```

references.solution.tsx:
// v3rc01_component_api_design / ex3 - reference solution.
import { createContext, useContext, useMemo, useState } from "react";
import type { ReactElement, ReactNode } from "react";

type TabsValue = { value: string; select: (next: string) => void };

// Module-private on purpose: exporting it would make the shape of this object
// part of the public API, and renaming `value` would then be a breaking change.
const TabsContext = createContext<TabsValue | null>(null);

function useTabsContext(part: string): TabsValue {
  const ctx = useContext(TabsContext);
  if (!ctx) {
    throw new Error(`<${part}> must be rendered inside <Tabs>`);
  }
  return ctx;
}

export function Tabs({
  defaultValue,
  children,
}: {
  defaultValue: string;
  children: ReactNode;
}): ReactElement {
  const [value, setValue] = useState(defaultValue);
  // Without the memo, every render of Tabs hands consumers a new object and
  // re-renders all of them, however unrelated the cause.
  const ctx = useMemo<TabsValue>(() => ({ value, select: setValue }), [value]);
  return <TabsContext value={ctx}>{children}</TabsContext>;
}

export function TabList({ children }: { children: ReactNode }): ReactElement {
  useTabsContext("TabList");
  return <div role="tablist">{children}</div>;
}

export function Tab({
  value,
  children,
}: {
  value: string;
  children: ReactNode;
}): ReactElement {
  const ctx = useTabsContext("Tab");
  const selected = ctx.value === value;
  return (
    <button
      type="button"
      role="tab"
      aria-selected={selected}
      onClick={() => ctx.select(value)}
    >
      {children}
    </button>
  );
}

export function TabPanel({
  value,
  children,
}: {
  value: string;
  children: ReactNode;
}): ReactElement | null {
  const ctx = useTabsContext("TabPanel");
  if (ctx.value !== value) return null;
  return <div role="tabpanel">{children}</div>;
}

// v3rc01_component_api_design / ex4 - reference solution.
import type { ReactElement, ReactNode } from "react";

export type ActionProps =
  | { kind: "link"; href: string; children: ReactNode }
  | { kind: "button"; onClick: () => void; children: ReactNode }
  | { kind: "submit"; children: ReactNode };

export function Action(props: ActionProps): ReactElement {
  switch (props.kind) {
    case "link":
      return <a href={props.href}>{props.children}</a>;
    case "button":
      return (
        <button type="button" onClick={props.onClick}>
          {props.children}
        </button>
      );
    case "submit":
      return <button type="submit">{props.children}</button>;
    default: {
      // If a fourth member is added to ActionProps and not handled above,
      // `props` is no longer narrowed to `never` here and this line stops
      // compiling - which is exactly the reminder you want.
      const unhandled: never = props;
      throw new Error(`unhandled action: ${JSON.stringify(unhandled)}`);
    }
  }
}

