## Exercise 5 — controlled, uncontrolled, or both

Edit `ex5/solution.tsx`. `Rating` must work in both modes, like every real
library component.

Export:

```tsx
export function Rating(props: {
  value?: number;
  defaultValue?: number;
  onChange?: (next: number) => void;
  max?: number;
}): ReactElement;
```

Behaviour:

- render `max` (default `5`) buttons, each `<button type="button">` with an
  accessible name `Rate <n>` — use `aria-label`;
- each button's `aria-pressed` is `true` when its number is less than or equal
  to the current rating;
- **uncontrolled** (`value` was `undefined` on the first render): the component
  keeps the rating in its own state, starting at `defaultValue ?? 0`, updates it
  on click, and still calls `onChange`;
- **controlled** (`value` was defined on the first render): the displayed
  rating is always the `value` prop, clicking does **not** change what is
  displayed on its own, and `onChange` is called with the clicked number;
- the mode is decided on the first render and never changes. If a controlled
  instance later receives `value === undefined`, it stays controlled and keeps
  showing the last value it was given rather than silently reverting to
  internal state.

The gate mounts a controlled `Rating`, clicks star 3 with an `onChange` that
ignores the call, and asserts nothing visually changed; then re-renders with
`value={undefined}` and asserts the component did not switch modes.

```
uv run dojo test react v3rc01_component_api_design ex5
```

references.solution.tsx:
// v3rc01_component_api_design / ex5 - reference solution.
import { useRef, useState } from "react";
import type { ReactElement } from "react";

export function Rating({
  value,
  defaultValue,
  onChange,
  max = 5,
}: {
  value?: number;
  defaultValue?: number;
  onChange?: (next: number) => void;
  max?: number;
}): ReactElement {
  // A ref's initial value is only evaluated on mount, so this freezes the
  // controlled/uncontrolled decision for the life of the component. Computing
  // it fresh each render would let a transient `undefined` flip modes.
  const isControlled = useRef(value !== undefined).current;
  const [internal, setInternal] = useState(defaultValue ?? 0);

  // Remember the last defined controlled value so a controlled instance that
  // is handed `undefined` keeps displaying something sensible instead of
  // falling back to internal state.
  const lastControlled = useRef(value ?? defaultValue ?? 0);
  if (isControlled && value !== undefined) {
    lastControlled.current = value;
  }

  const rating = isControlled ? lastControlled.current : internal;

  function pick(next: number) {
    if (!isControlled) setInternal(next);
    onChange?.(next);
  }

  return (
    <div>
      {Array.from({ length: max }, (_, index) => index + 1).map((n) => (
        <button
          key={n}
          type="button"
          aria-label={`Rate ${n}`}
          aria-pressed={n <= rating}
          onClick={() => pick(n)}
        >
          {n <= rating ? "★" : "☆"}
        </button>
      ))}
    </div>
  );
}

// v3rc01_component_api_design / ex6 - reference solution.
import type { ComponentPropsWithoutRef, ElementType, ReactElement, ReactNode } from "react";

type TextOwnProps<T extends ElementType> = {
  as?: T;
  tone?: "default" | "muted";
  children: ReactNode;
};

export type TextProps<T extends ElementType> = TextOwnProps<T> &
  Omit<ComponentPropsWithoutRef<T>, keyof TextOwnProps<T>>;

export function Text<T extends ElementType = "span">({
  as,
  tone = "default",
  children,
  ...rest
}: TextProps<T>): ReactElement {
  // Capitalised local: JSX resolves lowercase identifiers as literal HTML tag
  // names, so `const component = as` would render <component>.
  const Component = (as ?? "span") as ElementType;

  // Spread first, then the attributes this component guarantees. Reversing
  // these two lines would let a caller pass data-tone and win.
  return (
    <Component {...rest} data-tone={tone}>
      {children}
    </Component>
  );
}

