## Exercise 7 — a small imperative surface

Edit `ex7/solution.tsx`. A search field that a parent occasionally needs to
drive imperatively, without handing out the DOM node.

Export:

```tsx
export type SearchFieldHandle = {
  focus: () => void;
  clear: () => void;
};

export function SearchField(props: {
  ref?: Ref<SearchFieldHandle>;
  label: string;
  onSearch: (query: string) => void;
}): ReactElement;
```

Behaviour:

- renders a `<label>` wired to a controlled `<input type="search">` and a
  `<button type="submit">Search</button>`, inside a `<form>`;
- submitting the form calls `onSearch` with the current query and does not
  reload the page;
- the ref exposes exactly two methods: `focus()` moves DOM focus to the input,
  `clear()` empties the query **and** focuses the input;
- nothing else is reachable through the ref — no `value`, no `input` node, no
  `select()`.

Use React 19's plain `ref` prop. `forwardRef` is deprecated and the gate fails
if the module imports it.

```
uv run dojo test react v3rc01_component_api_design ex7
```

references.solution.tsx:
// v3rc01_component_api_design / ex7 - reference solution.
import { useId, useImperativeHandle, useRef, useState } from "react";
import type { FormEvent, ReactElement, Ref } from "react";

export type SearchFieldHandle = {
  focus: () => void;
  clear: () => void;
};

export function SearchField({
  ref,
  label,
  onSearch,
}: {
  // React 19: ref is a plain prop on function components. No forwardRef.
  ref?: Ref<SearchFieldHandle>;
  label: string;
  onSearch: (query: string) => void;
}): ReactElement {
  const inputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState("");
  const id = useId();

  // Exactly two methods reach the caller. The DOM node stays private, so it
  // cannot become part of the contract by accident.
  useImperativeHandle(
    ref,
    () => ({
      focus: () => inputRef.current?.focus(),
      clear: () => {
        setQuery("");
        inputRef.current?.focus();
      },
    }),
    // setQuery is stable across renders, so nothing here goes stale.
    []
  );

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSearch(query);
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor={id}>{label}</label>
      <input
        id={id}
        ref={inputRef}
        type="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      <button type="submit">Search</button>
    </form>
  );
}

