## Exercise 8 — headless hook, thin component

Edit `ex8/solution.tsx`. Split a disclosure into reusable behaviour and
disposable markup.

Export:

```tsx
export function useDisclosure(options?: { defaultOpen?: boolean }): {
  open: boolean;
  getTriggerProps: <P extends { onClick?: MouseEventHandler }>(
    props?: P
  ) => P & { onClick: MouseEventHandler; "aria-expanded": boolean; type: "button" };
  getPanelProps: <P extends object>(props?: P) => P & { hidden: boolean };
};

export function Disclosure(props: {
  label: string;
  children: ReactNode;
  defaultOpen?: boolean;
}): ReactElement;
```

Behaviour:

- `useDisclosure` owns the open/closed state, starting at `defaultOpen ?? false`;
- `getTriggerProps()` returns props for a button: `type: "button"`,
  `aria-expanded` reflecting the state, and an `onClick` that toggles it;
- if the caller passes their own `onClick` to `getTriggerProps`, **both** run —
  the caller's first, then the toggle. It must not be replaced;
- `getPanelProps()` returns `hidden: true` when closed;
- `Disclosure` is a thin component built entirely on the hook: a `<button>` with
  the label and a `<div>` with the children.

The gate calls `getTriggerProps({ onClick: spy, id: "t" })`, renders the result
on a button, clicks it once, and asserts the spy ran **and** the panel opened,
and that `id` survived.

```
uv run dojo test react v3rc01_component_api_design ex8
```

references.solution.tsx:
// v3rc01_component_api_design / ex8 - reference solution.
import { useCallback, useState } from "react";
import type { MouseEventHandler, ReactElement, ReactNode } from "react";

export function useDisclosure(options?: { defaultOpen?: boolean }) {
  const [open, setOpen] = useState(options?.defaultOpen ?? false);

  const getTriggerProps = useCallback(
    <P extends { onClick?: MouseEventHandler }>(props?: P) => ({
      ...(props ?? ({} as P)),
      type: "button" as const,
      "aria-expanded": open,
      // Merge, do not replace: the caller's handler runs first and then ours,
      // so passing onClick to the getter does not silently break the toggle.
      onClick: ((event) => {
        props?.onClick?.(event);
        setOpen((current) => !current);
      }) as MouseEventHandler,
    }),
    [open]
  );

  const getPanelProps = useCallback(
    <P extends object>(props?: P) => ({
      ...(props ?? ({} as P)),
      hidden: !open,
    }),
    [open]
  );

  return { open, getTriggerProps, getPanelProps };
}

// The presentational half holds no state at all. A redesign rewrites this
// function and never touches the hook above it.
export function Disclosure({
  label,
  children,
  defaultOpen,
}: {
  label: string;
  children: ReactNode;
  defaultOpen?: boolean;
}): ReactElement {
  const { getTriggerProps, getPanelProps } = useDisclosure({ defaultOpen });
  return (
    <div>
      <button {...getTriggerProps()}>{label}</button>
      <div {...getPanelProps()}>{children}</div>
    </div>
  );
}

