// v3rc01_component_api_design / challenge - reference solution.
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import type {
  ComponentPropsWithoutRef,
  ElementType,
  MouseEventHandler,
  ReactElement,
  ReactNode,
} from "react";

type SelectContextValue = {
  open: boolean;
  toggle: () => void;
  close: () => void;
  value: string | undefined;
  select: (next: string) => void;
  register: (value: string, label: string) => void;
  unregister: (value: string) => void;
  labelFor: (value: string | undefined) => string | undefined;
};

const SelectContext = createContext<SelectContextValue | null>(null);

function useSelectContext(part: string): SelectContextValue {
  const ctx = useContext(SelectContext);
  if (!ctx) throw new Error(`<${part}> must be rendered inside <Select>`);
  return ctx;
}

export function Select({
  value,
  defaultValue,
  onChange,
  children,
}: {
  value?: string;
  defaultValue?: string;
  onChange?: (next: string) => void;
  children: ReactNode;
}): ReactElement {
  // --- hybrid control, frozen at mount (same rule as ex5) ---------------
  const isControlled = useRef(value !== undefined).current;
  const [internal, setInternal] = useState<string | undefined>(defaultValue);
  const lastControlled = useRef<string | undefined>(value ?? defaultValue);
  if (isControlled && value !== undefined) lastControlled.current = value;
  const resolved = isControlled ? lastControlled.current : internal;

  const [open, setOpen] = useState(false);

  // --- label registry ---------------------------------------------------
  // Options publish their labels upward so the trigger can render one without
  // inspecting children. The ref holds the data; the counter forces the
  // re-render that lets the trigger pick it up.
  const labels = useRef(new Map<string, string>());
  const [, bumpVersion] = useState(0);

  const register = useCallback((optionValue: string, label: string) => {
    if (labels.current.get(optionValue) === label) return;
    labels.current.set(optionValue, label);
    bumpVersion((n) => n + 1);
  }, []);

  const unregister = useCallback((optionValue: string) => {
    if (!labels.current.delete(optionValue)) return;
    bumpVersion((n) => n + 1);
  }, []);

  const select = useCallback(
    (next: string) => {
      if (!isControlled) setInternal(next);
      onChange?.(next);
      setOpen(false);
    },
    [isControlled, onChange]
  );

  const ctx = useMemo<SelectContextValue>(
    () => ({
      open,
      toggle: () => setOpen((current) => !current),
      close: () => setOpen(false),
      value: resolved,
      select,
      register,
      unregister,
      // Falls back to the raw value until the matching option has registered.
      labelFor: (v) => (v === undefined ? undefined : labels.current.get(v) ?? v),
    }),
    [open, resolved, select, register, unregister]
  );

  return <SelectContext value={ctx}>{children}</SelectContext>;
}

// --- polymorphic trigger; its generic never mentions the context ---------
type TriggerOwnProps<T extends ElementType> = { as?: T; placeholder?: string };

export function SelectTrigger<T extends ElementType = "button">({
  as,
  placeholder = "Select…",
  ...rest
}: TriggerOwnProps<T> &
  Omit<ComponentPropsWithoutRef<T>, keyof TriggerOwnProps<T> | "children">): ReactElement {
  const ctx = useSelectContext("SelectTrigger");
  const Component = (as ?? "button") as ElementType;
  const label = ctx.labelFor(ctx.value);

  const callerOnClick = (rest as { onClick?: MouseEventHandler }).onClick;
  const onClick: MouseEventHandler = (event) => {
    callerOnClick?.(event);
    ctx.toggle();
  };

  return (
    <Component
      {...rest}
      {...(Component === "button" ? { type: "button" as const } : null)}
      aria-haspopup="listbox"
      aria-expanded={ctx.open}
      onClick={onClick}
    >
      {label ?? placeholder}
    </Component>
  );
}

export function SelectOptions({ children }: { children: ReactNode }): ReactElement | null {
  const ctx = useSelectContext("SelectOptions");
  if (!ctx.open) return null;
  return <ul role="listbox">{children}</ul>;
}

export function SelectOption({
  value,
  children,
}: {
  value: string;
  children: ReactNode;
}): ReactElement {
  const ctx = useSelectContext("SelectOption");
  const label = typeof children === "string" ? children : value;

  // Registration is an effect: writing to the parent's state during this
  // component's render is the "cannot update a component while rendering a
  // different component" error.
  useEffect(() => {
    ctx.register(value, label);
    return () => ctx.unregister(value);
  }, [ctx, value, label]);

  return (
    <li
      role="option"
      aria-selected={ctx.value === value}
      onClick={() => ctx.select(value)}
    >
      {children}
    </li>
  );
}

