// v3rc01_component_api_design / review1 - reference solution.
import type { ReactElement, ReactNode } from "react";

// `level` stayed a prop because the component interprets it: it decides the
// data attribute, the default icon and (in a real system) the colour tokens,
// and the set of legal values is closed by design.
// `showIcon` went away because the presence of the `icon` slot is the boolean.
// `dismissible`/`onDismiss` went away because a dismiss control is a button the
// caller can put in `actions`, and the component never needed to understand it.
// `actionLabel`/`onAction` went away for the same reason, and the slot version
// additionally supports two actions, which the prop version never could.

const DEFAULT_ICONS: Record<AlertLevel, string> = {
  info: "i",
  warning: "!",
  danger: "×",
};

export type AlertLevel = "info" | "warning" | "danger";

export function Alert({
  level,
  icon,
  children,
  actions,
}: {
  level: AlertLevel;
  icon?: ReactNode;
  children: ReactNode;
  actions?: ReactNode;
}): ReactElement {
  const resolvedIcon = icon === undefined ? DEFAULT_ICONS[level] : icon;

  return (
    <div role="alert" data-level={level}>
      {resolvedIcon != null && <span className="alert-icon">{resolvedIcon}</span>}
      <div className="alert-content">{children}</div>
      {actions != null && <div className="alert-actions">{actions}</div>}
    </div>
  );
}

// The title's wrapper is rendered by the title itself, so Alert does not have
// to know whether one was supplied - it just renders whatever children it got.
export function AlertTitle({ children }: { children: ReactNode }): ReactElement {
  return <strong className="alert-title">{children}</strong>;
}

export function AlertMessage({ children }: { children: ReactNode }): ReactElement {
  return <p className="alert-message">{children}</p>;
}

