// v3rc02_error_boundaries / ex1 - reference solution.
import { Component } from "react";
import type { ReactNode } from "react";

type Props = { children: ReactNode; fallback: ReactNode };
type State = { error: Error | null };

export class ErrorBoundary extends Component<Props, State> {
  // Class property instead of a constructor: less ceremony, same result.
  state: State = { error: null };

  // Static and pure: React may run the failed render more than once, so this
  // method must not have side effects. Reporting belongs in componentDidCatch.
  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  render() {
    // `!== null` rather than truthiness: a thrown falsy value still counts.
    return this.state.error !== null ? this.props.fallback : this.props.children;
  }
}

