// v3rc02_error_boundaries / ex2 - reference solution.
import { Component } from "react";
import type { ErrorInfo, ReactNode } from "react";

export type ErrorReport = {
  message: string;
  componentStack: string;
};

type Props = {
  children: ReactNode;
  fallback: ReactNode;
  onError: (report: ErrorReport) => void;
};
type State = { error: Error | null };

export class ReportingBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  // Commit phase: side effects are allowed here, and React calls it exactly
  // once per caught error.
  componentDidCatch(error: Error, info: ErrorInfo) {
    try {
      this.props.onError({
        message: error.message,
        componentStack: info.componentStack ?? "",
      });
    } catch {
      // A reporter that throws would escalate a handled error into an
      // unhandled one at the next boundary up. Contain it here.
    }
  }

  render() {
    return this.state.error !== null ? this.props.fallback : this.props.children;
  }
}

// v3rc02_error_boundaries / ex3 - reference solution.
import { useCallback, useState } from "react";
import type { ReactElement } from "react";

// Converts any non-render failure into something a boundary can see, by
// storing it and re-throwing during the next render.
export function useThrowToBoundary() {
  const [error, setError] = useState<Error | null>(null);
  // Runs during render, which is the only phase a boundary can catch.
  if (error) throw error;
  return useCallback((thrown: unknown) => {
    setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
  }, []);
}

export function DangerButton({
  label,
  action,
}: {
  label: string;
  action: () => void;
}): ReactElement {
  const throwToBoundary = useThrowToBoundary();

  return (
    <button
      type="button"
      onClick={() => {
        try {
          action();
        } catch (thrown) {
          // The click handler runs on the browser's stack, not React's, so
          // the boundary never saw this. Hand it back to the render phase.
          throwToBoundary(thrown);
        }
      }}
    >
      {label}
    </button>
  );
}

