// v3rc02_error_boundaries / ex4 - reference solution.
import { Component } from "react";
import type { ReactNode } from "react";

type Props = {
  children: ReactNode;
  fallback: ReactNode;
  resetKeys?: unknown[];
};
type State = { error: Error | null };

function keysChanged(a: unknown[], b: unknown[]): boolean {
  if (a.length !== b.length) return true;
  // Object.is rather than ===, so a NaN key does not compare unequal to itself
  // and trigger an endless reset.
  return a.some((value, index) => !Object.is(value, b[index]));
}

export class ResettableBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidUpdate(prevProps: Props) {
    // Only relevant while displaying a fallback; otherwise this would setState
    // on every single update.
    if (this.state.error === null) return;

    const previous = prevProps.resetKeys ?? [];
    const next = this.props.resetKeys ?? [];

    // Element-wise, because callers write resetKeys={[id]} inline and the
    // array identity changes on every render.
    if (keysChanged(previous, next)) {
      this.setState({ error: null });
    }
  }

  render() {
    return this.state.error !== null ? this.props.fallback : this.props.children;
  }
}

