// v3rc02_error_boundaries / ex5 - reference solution.
import { Component, Fragment } from "react";
import type { ReactNode } from "react";

type Props = {
  children: ReactNode;
  fallback: (args: { error: Error; reset: () => void }) => ReactNode;
};
type State = { error: Error | null; attempt: number };

export class RetryBoundary extends Component<Props, State> {
  state: State = { error: null, attempt: 0 };

  static getDerivedStateFromError(error: Error): Pick<State, "error"> {
    return { error };
  }

  // Class property: one function per instance, stable identity, safe to hand
  // to a memoised button.
  reset = () => {
    this.setState((current) => ({ error: null, attempt: current.attempt + 1 }));
  };

  render() {
    const { error, attempt } = this.state;
    if (error !== null) {
      return this.props.fallback({ error, reset: this.reset });
    }
    // Keying on the attempt count means reset unmounts and remounts the
    // subtree. Clearing the error alone would re-render the same instances,
    // which still hold whatever made them throw.
    return <Fragment key={attempt}>{this.props.children}</Fragment>;
  }
}

// v3rc02_error_boundaries / ex6 - reference solution.
import { Component } from "react";
import type { ReactElement, ReactNode } from "react";

type BoundaryProps = { children: ReactNode; fallback: ReactNode };
type BoundaryState = { error: Error | null };

class WidgetBoundary extends Component<BoundaryProps, BoundaryState> {
  state: BoundaryState = { error: null };
  static getDerivedStateFromError(error: Error): BoundaryState {
    return { error };
  }
  render() {
    return this.state.error !== null ? this.props.fallback : this.props.children;
  }
}

export type WidgetSpec = {
  id: string;
  kind: "revenue" | "traffic" | "notes";
  data: unknown;
};

function Widget({ kind, data }: { kind: WidgetSpec["kind"]; data: unknown }) {
  if (kind === "revenue") return <RevenueWidget data={data} />;
  if (kind === "traffic") return <TrafficWidget data={data} />;
  return <NotesWidget />;
}

export function Dashboard({ widgets }: { widgets: WidgetSpec[] }): ReactElement {
  return (
    <div>
      {widgets.map((widget) => (
        // One boundary per widget, inside the section. A single boundary
        // around the map would unmount every sibling on any failure, taking
        // the notes text with it.
        <section key={widget.id} data-widget={widget.id}>
          <WidgetBoundary
            fallback={<p role="status">Could not load {widget.id}</p>}
          >
            <Widget kind={widget.kind} data={widget.data} />
          </WidgetBoundary>
        </section>
      ))}
    </div>
  );
}

// --- widgets supplied by the stub, reproduced here for completeness --------

function RevenueWidget({ data }: { data: unknown }): ReactElement {
  const value = (data as { total: number }).total;
  return <p>Revenue: {value}</p>;
}

function TrafficWidget({ data }: { data: unknown }): ReactElement {
  const visits = (data as { visits?: number } | null)?.visits ?? 0;
  return <p>Visits: {visits}</p>;
}

function NotesWidget(): ReactElement {
  return (
    <label>
      Notes
      <input type="text" defaultValue="" />
    </label>
  );
}

