## Exercise 7 — Suspense and boundaries together

Edit `ex7/solution.tsx`. Make pending and failed visibly different, and make
retry work for both.

Export:

```tsx
export function AsyncSection(props: {
  load: (attempt: number) => Promise<string>;
  label: string;
}): ReactElement;
```

Behaviour:

- while the promise from `load` is pending, render
  `<p role="status">Loading {label}</p>`;
- when it resolves, render `<p>{value}</p>`;
- when it rejects, render `<p role="alert">{label} failed</p>` and a
  `<button type="button">Try again</button>`;
- clicking Try again calls `load` with the next attempt number and returns to
  the loading state — it must not immediately re-show the failure.

The stub gives you a tiny `use`-compatible resource helper; the child reads it
with React's `use()`. Note that `load` is called once per attempt and the result
is cached for that attempt, so a retry that does not change the attempt number
re-reads the same rejected promise.

```
uv run dojo test react v3rc02_error_boundaries ex7
```

references.solution.tsx:
// v3rc02_error_boundaries / ex7 - reference solution.
import { Component, Suspense, use, useCallback, useMemo, useState } from "react";
import type { ReactElement, ReactNode } from "react";

type BoundaryProps = {
  children: ReactNode;
  fallback: ReactNode;
  resetKeys: unknown[];
};
type BoundaryState = { error: Error | null };

class Boundary extends Component<BoundaryProps, BoundaryState> {
  state: BoundaryState = { error: null };
  static getDerivedStateFromError(error: Error): BoundaryState {
    return { error };
  }
  componentDidUpdate(prev: BoundaryProps) {
    if (this.state.error === null) return;
    const a = prev.resetKeys;
    const b = this.props.resetKeys;
    if (a.length !== b.length || a.some((v, i) => !Object.is(v, b[i]))) {
      this.setState({ error: null });
    }
  }
  render() {
    return this.state.error !== null ? this.props.fallback : this.props.children;
  }
}

function Value({ promise }: { promise: Promise<string> }): ReactElement {
  // `use` suspends on a pending promise and throws on a rejected one, which is
  // what lets one child feed both fallbacks above it.
  const value = use(promise);
  return <p>{value}</p>;
}

export function AsyncSection({
  load,
  label,
}: {
  load: (attempt: number) => Promise<string>;
  label: string;
}): ReactElement {
  const [attempt, setAttempt] = useState(0);

  // One promise per attempt. Retrying without changing the attempt would
  // re-read the same rejected promise and fail again before the loading state
  // was ever visible.
  const promise = useMemo(() => load(attempt), [load, attempt]);

  const retry = useCallback(() => setAttempt((n) => n + 1), []);

  return (
    // Boundary outside Suspense: a failure replaces the whole section, and the
    // error UI is not itself inside the suspending subtree.
    <Boundary
      resetKeys={[attempt]}
      fallback={
        <>
          <p role="alert">{label} failed</p>
          <button type="button" onClick={retry}>
            Try again
          </button>
        </>
      }
    >
      <Suspense fallback={<p role="status">Loading {label}</p>}>
        <Value key={attempt} promise={promise} />
      </Suspense>
    </Boundary>
  );
}

