## Exercise 8 — routing a promise rejection into a boundary

Edit `ex8/solution.tsx`. Not every async failure should reach a boundary. Build
the hook that lets a component choose.

Export:

```tsx
export function useAsyncAction<T>(
  run: () => Promise<T>,
  options?: { escalate?: (error: Error) => boolean }
): {
  status: "idle" | "pending" | "done" | "failed";
  error: Error | null;
  start: () => void;
};
```

Behaviour:

- `start()` sets `status` to `"pending"` and calls `run()`;
- on resolve, `status` becomes `"done"`;
- on reject, normalise the thrown value to an `Error`, then ask
  `options.escalate(error)`:
  - if it returns `true` (or `escalate` was not supplied), re-throw the error
    during the next render so the enclosing error boundary catches it;
  - if it returns `false`, keep it locally: `status` becomes `"failed"` and
    `error` holds it, and no boundary is involved;
- calling `start()` again after a local failure clears `error` and retries;
- a rejection arriving after the component unmounted must not set state.

The gate uses `escalate: (e) => !(e instanceof ValidationError)` — validation
failures stay local and everything else hits the boundary.

```
uv run dojo test react v3rc02_error_boundaries ex8
```

references.solution.tsx:
// v3rc02_error_boundaries / ex8 - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

type Status = "idle" | "pending" | "done" | "failed";

function toError(thrown: unknown): Error {
  return thrown instanceof Error ? thrown : new Error(String(thrown));
}

export function useAsyncAction<T>(
  run: () => Promise<T>,
  options?: { escalate?: (error: Error) => boolean }
) {
  // Errors destined for the boundary. Thrown during render - the only phase a
  // boundary can catch.
  const [escalated, setEscalated] = useState<Error | null>(null);
  if (escalated) throw escalated;

  const [status, setStatus] = useState<Status>("idle");
  const [error, setError] = useState<Error | null>(null);

  const alive = useRef(true);
  useEffect(() => {
    // Reset on mount as well as clearing on unmount: StrictMode mounts,
    // unmounts and remounts in development, and without this the second mount
    // would start already marked dead.
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  const escalate = options?.escalate;

  const start = useCallback(() => {
    // Cleared synchronously so "pending" and a stale error are never on screen
    // at the same time.
    setError(null);
    setStatus("pending");

    run().then(
      () => {
        if (alive.current) setStatus("done");
      },
      (thrown: unknown) => {
        if (!alive.current) return;
        const err = toError(thrown);
        // Default is to escalate: an unclassified failure is one you did not
        // expect, which is exactly what boundaries are for.
        if (escalate ? escalate(err) : true) {
          setEscalated(err);
        } else {
          setError(err);
          setStatus("failed");
        }
      }
    );
  }, [run, escalate]);

  return { status, error, start };
}

