## Challenge — a resilient widget host

Edit `challenge/solution.tsx`. One host component that isolates, reports,
retries and degrades.

Export:

```tsx
export type WidgetDescriptor = {
  id: string;
  title: string;
  load: (attempt: number) => Promise<{ render: () => ReactNode }>;
  optional?: boolean;
};

export function WidgetHost(props: {
  widgets: WidgetDescriptor[];
  onError: (report: { id: string; message: string; componentStack: string }) => void;
}): ReactElement;
```

Behaviour, per widget, independently:

- `<section data-widget={id}>` with an `<h2>` containing the title, always;
- while loading: `<p role="status">Loading</p>`;
- on success: the result of `render()`;
- on failure: report once via `onError` with the widget's id, then —
  - if `optional` is true, render nothing below the heading (a degraded but
    quiet failure),
  - otherwise render `<p role="alert">Could not load {title}</p>` and a
    `Try again` button;
- Try again must return the widget to the loading state and call `load` with an
  incremented attempt. A second failure must report again — one report per
  failed attempt, not one per widget;
- a failure in one widget must leave every other widget's state untouched.

Honest difficulty note: nothing new after ex1–ex8. The hard part is the retry
ordering — the boundary reset, the new promise, and the remount have to happen
from one state change, or you will see a flash of the stale error.

```
uv run dojo test react v3rc02_error_boundaries challenge
```

references.solution.tsx:
// v3rc02_error_boundaries / challenge - reference solution.
import { Component, Suspense, use, useCallback, useMemo, useState } from "react";
import type { ErrorInfo, ReactElement, ReactNode } from "react";

export type WidgetDescriptor = {
  id: string;
  title: string;
  load: (attempt: number) => Promise<{ render: () => ReactNode }>;
  optional?: boolean;
};

type Report = { id: string; message: string; componentStack: string };

type BoundaryProps = {
  children: ReactNode;
  fallback: (reset: () => void) => ReactNode;
  onCatch: (error: Error, info: ErrorInfo) => void;
  resetKeys: unknown[];
};
type BoundaryState = { error: Error | null };

class Boundary extends Component<BoundaryProps, BoundaryState> {
  state: BoundaryState = { error: null };

  static getDerivedStateFromError(error: Error): BoundaryState {
    return { error };
  }

  // Once per caught error. Reporting from the fallback's render instead would
  // fire on every unrelated re-render of the host.
  componentDidCatch(error: Error, info: ErrorInfo) {
    try {
      this.props.onCatch(error, info);
    } catch {
      /* a throwing reporter must not escalate a handled error */
    }
  }

  componentDidUpdate(prev: BoundaryProps) {
    if (this.state.error === null) return;
    const a = prev.resetKeys;
    const b = this.props.resetKeys;
    if (a.length !== b.length || a.some((v, i) => !Object.is(v, b[i]))) {
      this.setState({ error: null });
    }
  }

  reset = () => this.setState({ error: null });

  render() {
    return this.state.error !== null
      ? this.props.fallback(this.reset)
      : this.props.children;
  }
}

function WidgetBody({
  promise,
}: {
  promise: Promise<{ render: () => ReactNode }>;
}): ReactElement {
  const widget = use(promise);
  return <>{widget.render()}</>;
}

function HostedWidget({
  descriptor,
  onError,
}: {
  descriptor: WidgetDescriptor;
  onError: (report: Report) => void;
}): ReactElement {
  const { id, title, load, optional } = descriptor;
  const [attempt, setAttempt] = useState(0);

  // The attempt number is the single source of truth: it keys the promise, the
  // boundary reset and the remount, so one setState moves all three together
  // and there is no ordering to get wrong.
  const promise = useMemo(() => load(attempt), [load, attempt]);
  const retry = useCallback(() => setAttempt((n) => n + 1), []);

  return (
    <section data-widget={id}>
      <h2>{title}</h2>
      <Boundary
        resetKeys={[attempt]}
        onCatch={(error, info) =>
          onError({
            id,
            message: error.message,
            componentStack: info.componentStack ?? "",
          })
        }
        fallback={() =>
          optional ? null : (
            <>
              <p role="alert">Could not load {title}</p>
              <button type="button" onClick={retry}>
                Try again
              </button>
            </>
          )
        }
      >
        <Suspense fallback={<p role="status">Loading</p>}>
          <WidgetBody key={attempt} promise={promise} />
        </Suspense>
      </Boundary>
    </section>
  );
}

export function WidgetHost({
  widgets,
  onError,
}: {
  widgets: WidgetDescriptor[];
  onError: (report: Report) => void;
}): ReactElement {
  // The host contains no error logic at all - every widget is independently
  // mounted, so one failure cannot touch another's state.
  return (
    <div>
      {widgets.map((descriptor) => (
        <HostedWidget key={descriptor.id} descriptor={descriptor} onError={onError} />
      ))}
    </div>
  );
}

// v3rc02_error_boundaries / review1 - reference solution.
import { useCallback, useEffect, useState } from "react";
import type { ReactElement } from "react";

// React catches what React called. Render bodies, lazy state initialisers and
// effect bodies are all invoked by React inside its own error handling.
// Browser-invoked callbacks - DOM events, timers, microtasks - are not.
export const CAUGHT_BY_BOUNDARY: Record<string, boolean> = {
  RenderThrow: true,
  EffectThrow: true,
  InitThrow: true,
  ClickThrow: false,
  TimerThrow: false,
  PromiseThrow: false,
};

function useThrowToBoundary() {
  const [error, setError] = useState<Error | null>(null);
  if (error) throw error;
  return useCallback((thrown: unknown) => {
    setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
  }, []);
}

// --- the three that already reach a boundary, unchanged -------------------

export function RenderThrow(): ReactElement {
  throw new Error("RenderThrow");
}

export function EffectThrow(): ReactElement {
  useEffect(() => {
    throw new Error("EffectThrow");
  }, []);
  return <p>effect</p>;
}

export function InitThrow(): ReactElement {
  const [value] = useState(() => {
    throw new Error("InitThrow");
  });
  return <p>{String(value)}</p>;
}

// --- the three repairs ----------------------------------------------------

export function ClickThrow(): ReactElement {
  const throwToBoundary = useThrowToBoundary();
  return (
    <button
      type="button"
      onClick={() => {
        try {
          throw new Error("ClickThrow");
        } catch (thrown) {
          throwToBoundary(thrown);
        }
      }}
    >
      click
    </button>
  );
}

export function TimerThrow(): ReactElement {
  const throwToBoundary = useThrowToBoundary();
  useEffect(() => {
    // The try must be inside the callback: setTimeout itself returns
    // immediately and never throws.
    const id = setTimeout(() => {
      try {
        throw new Error("TimerThrow");
      } catch (thrown) {
        throwToBoundary(thrown);
      }
    }, 0);
    return () => clearTimeout(id);
  }, [throwToBoundary]);
  return <p>timer</p>;
}

export function PromiseThrow(): ReactElement {
  const throwToBoundary = useThrowToBoundary();
  return (
    <button
      type="button"
      onClick={async () => {
        // `await` inside try/catch is the one shape that actually catches a
        // rejection; a plain try around a promise-returning call does not.
        try {
          await Promise.reject(new Error("PromiseThrow"));
        } catch (thrown) {
          throwToBoundary(thrown);
        }
      }}
    >
      go
    </button>
  );
}

