```

references.solution.tsx:
// v3rc03_accessibility_focus / ex2 - reference solution.
import { useId } from "react";
import type { ReactElement } from "react";

export function Field({
  label,
  hint,
  error,
  value,
  onChange,
}: {
  label: string;
  hint?: string;
  error?: string;
  value: string;
  onChange: (next: string) => void;
}): ReactElement {
  // One id per instance, stable across renders and identical on server and
  // client - which is why this is a hook and not a module counter.
  const id = useId();
  const hintId = `${id}-hint`;
  const errorId = `${id}-error`;

  // Space-separated, in announcement order, and undefined (not "") when empty
  // so React omits the attribute rather than emitting a dangling reference.
  const describedBy =
    [hint ? hintId : null, error ? errorId : null].filter(Boolean).join(" ") ||
    undefined;

  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input
        id={id}
        type="text"
        value={value}
        onChange={(event) => onChange(event.target.value)}
        aria-describedby={describedBy}
        aria-invalid={error ? true : undefined}
      />
      {hint && <p id={hintId}>{hint}</p>}
      {error && <p id={errorId}>{error}</p>}
    </div>
  );
}

