references.solution.tsx:
// v3rc03_accessibility_focus / ex3 - reference solution.
import { useId, useState } from "react";
import type { ReactElement, ReactNode } from "react";

export function Disclosure({
  summary,
  children,
  onBodyRender,
}: {
  summary: string;
  children: ReactNode;
  onBodyRender?: () => void;
}): ReactElement {
  const [open, setOpen] = useState(false);
  const id = useId();
  const buttonId = `${id}-trigger`;
  const panelId = `${id}-panel`;

  return (
    <div>
      <button
        type="button"
        id={buttonId}
        // aria-expanded describes the control, so it lives here and not on the
        // panel. React renders a boolean aria-* value as "true"/"false", so
        // the attribute is present in both states.
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((current) => !current)}
      >
        {summary}
      </button>
      {/* Not rendered rather than hidden: a closed panel builds no elements,
          commits no DOM and runs no effects. */}
      {open && (
        <div id={panelId} role="region" aria-labelledby={buttonId}>
          <Body onRender={onBodyRender}>{children}</Body>
        </div>
      )}
    </div>
  );
}

function Body({
  children,
  onRender,
}: {
  children: ReactNode;
  onRender?: () => void;
}): ReactElement {
  onRender?.();
  return <>{children}</>;
}

