references.solution.tsx:
// v3rc03_accessibility_focus / ex4 - reference solution.
import { useId, useLayoutEffect, useRef } from "react";
import type { KeyboardEvent, ReactElement, ReactNode } from "react";

export function Dialog({
  title,
  onClose,
  children,
}: {
  title: string;
  onClose: () => void;
  children: ReactNode;
}): ReactElement {
  const ref = useRef<HTMLDivElement>(null);
  const titleId = useId();

  useLayoutEffect(() => {
    // Captured before we move focus, so we know where to put it back.
    const opener = document.activeElement as HTMLElement | null;
    ref.current?.focus();
    // Cleanup, not onClose: this runs however the dialog went away - Escape,
    // a route change, a parent unmounting it, a boundary catching an error.
    return () => opener?.focus();
    // useLayoutEffect so the move happens before paint; a useEffect can show
    // one frame with focus still behind the overlay.
  }, []);

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") {
      event.stopPropagation();
      onClose();
    }
  }

  return (
    <div
      ref={ref}
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      // The only legitimate non-zero tabIndex: focusable by script, not by Tab.
      tabIndex={-1}
      onKeyDown={handleKeyDown}
    >
      <h2 id={titleId}>{title}</h2>
      {children}
    </div>
  );
}

exercises.hints:
## Hint 1

`inert` is a real DOM property in current browsers — `element.inert = true` —
and it does everything at once: nothing inside can be focused, clicked, or seen
by assistive technology. Setting it on the background is one line and replaces
most of what hand-rolled traps were doing.

## Hint 2

For the trap, the shape is a `keydown` handler on the layer:

```tsx
if (event.key !== "Tab") return;
const items = focusableWithin(layerRef.current);
if (items.length === 0) return;
const first = items[0];
const last = items[items.length - 1];
```

then two cases: Shift+Tab while on `first` → prevent default and focus `last`;
Tab while on `last` → prevent default and focus `first`.

## Hint 3

Computing the focusable list is the fiddly part and it must happen on every Tab
rather than once on mount, because the layer's content changes. A selector
string plus a filter works:

```tsx
const SELECTOR =
  'a[href], button, input, select, textarea, [tabindex]';
Array.from(root.querySelectorAll<HTMLElement>(SELECTOR))
  .filter((el) => !el.hasAttribute("disabled") && el.tabIndex !== -1);
```

Add a visibility check — `el.offsetParent !== null` catches most hidden cases,
though it misses `position: fixed` elements, which is a known limitation worth a
comment.

references.solution.tsx:
// v3rc03_accessibility_focus / ex5 - reference solution.
import { useEffect, useRef } from "react";
import type { KeyboardEvent, ReactElement, ReactNode, RefObject } from "react";

const FOCUSABLE = "a[href], button, input, select, textarea, [tabindex]";

function focusableWithin(root: HTMLElement | null): HTMLElement[] {
  if (!root) return [];
  return Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
    (element) =>
      !element.hasAttribute("disabled") &&
      element.tabIndex !== -1 &&
      // Cheap visibility test. Misses position: fixed elements, which is a
      // known limitation of this approach.
      element.offsetParent !== null
  );
}

export function ModalLayer({
  backgroundRef,
  children,
}: {
  backgroundRef: RefObject<HTMLElement | null>;
  children: ReactNode;
}): ReactElement {
  const layerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const background = backgroundRef.current;
    if (!background) return;
    // Remember the previous value rather than assuming false: nested modals
    // would otherwise un-inert the page when the inner one closes.
    const previous = background.inert;
    background.inert = true;
    return () => {
      background.inert = previous;
    };
  }, [backgroundRef]);

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Tab") return;

    // Recomputed per keystroke: the layer's contents can change between them.
    const items = focusableWithin(layerRef.current);
    if (items.length === 0) return;

    const first = items[0];
    const last = items[items.length - 1];
    const active = document.activeElement;

    if (event.shiftKey && active === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && active === last) {
      event.preventDefault();
      first.focus();
    }
  }

  return (
    <div ref={layerRef} onKeyDown={handleKeyDown}>
      {children}
    </div>
  );
}

