## Exercise 6 — one tab stop, arrows inside

Edit `ex6/solution.tsx`. A toolbar that behaves like every other toolbar the
user has met.

Export:

```tsx
export function Toolbar(props: {
  items: { id: string; label: string; onActivate: () => void }[];
}): ReactElement;
```

Requirements:

- a `<div role="toolbar">` containing one `<button type="button">` per item;
- the whole toolbar is a **single** tab stop: exactly one button has
  `tabIndex={0}` and all others have `tabIndex={-1}`;
- ArrowRight and ArrowLeft move the active button, clamping at the ends (no
  wrapping); Home goes to the first, End to the last;
- moving the active index must also move real DOM focus;
- if `items` shrinks so the active index is past the end, clamp it during the
  next render — the toolbar must never be left with zero elements at
  `tabIndex={0}`;
- arrow keys that move focus call `preventDefault` so the page does not scroll.

The gate tabs into the toolbar, asserts focus is on the first button, presses
ArrowRight twice and End and Home, checking `document.activeElement` and the
`tabIndex` distribution each time, then re-renders with a shorter `items` array
and asserts a valid tab stop still exists.

```
uv run dojo test react v3rc03_accessibility_focus ex6
```

references.solution.tsx:
// v3rc03_accessibility_focus / ex6 - reference solution.
import { useRef, useState } from "react";
import type { KeyboardEvent, ReactElement } from "react";

type ToolbarItem = { id: string; label: string; onActivate: () => void };

export function Toolbar({ items }: { items: ToolbarItem[] }): ReactElement {
  const [active, setActive] = useState(0);
  const refs = useRef<(HTMLButtonElement | null)[]>([]);

  // Derived during render rather than corrected in an effect: if items shrinks
  // the toolbar must never be left with no element at tabIndex 0.
  const index = Math.min(active, Math.max(items.length - 1, 0));

  function move(next: number, event: KeyboardEvent<HTMLDivElement>) {
    event.preventDefault();
    setActive(next);
    // Setting tabIndex decides where Tab lands; it does not move focus. Both
    // are required.
    refs.current[next]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const last = items.length - 1;
    if (last < 0) return;

    switch (event.key) {
      case "ArrowRight":
        return move(Math.min(index + 1, last), event);
      case "ArrowLeft":
        return move(Math.max(index - 1, 0), event);
      case "Home":
        return move(0, event);
      case "End":
        return move(last, event);
      default:
        // Everything else keeps its default behaviour.
        return;
    }
  }

  return (
    <div role="toolbar" onKeyDown={handleKeyDown}>
      {items.map((item, i) => (
        <button
          key={item.id}
          type="button"
          ref={(node) => {
            refs.current[i] = node;
          }}
          tabIndex={i === index ? 0 : -1}
          onClick={() => {
            setActive(i);
            item.onActivate();
          }}
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}

