## Exercise 8 — a combobox where focus never leaves the input

Edit `ex8/solution.tsx`. The pattern that exists because DOM focus is a single
global thing.

Export:

```tsx
export function Combobox(props: {
  label: string;
  options: { id: string; label: string }[];
  onSelect: (id: string) => void;
}): ReactElement;
```

Requirements:

- an `<input type="text">` with `role="combobox"`, `aria-expanded`,
  `aria-controls` naming the listbox, and `aria-autocomplete="list"`;
- a `<ul role="listbox">` of `<li role="option">`, rendered only while open;
- typing filters the options by case-insensitive substring and opens the list;
- ArrowDown and ArrowUp move the *active option* — which is expressed by
  `aria-activedescendant` on the input pointing at the active option's id, and
  by `aria-selected` on that option — while DOM focus stays on the input the
  whole time;
- Enter selects the active option, calls `onSelect`, fills the input with its
  label and closes the list; Escape closes without selecting;
- when the filtered list changes, the active option resets to the first;
- the active option must be scrolled into view by your code.

The gate types, presses ArrowDown twice, asserts `document.activeElement` is
still the input, asserts `aria-activedescendant` names the second option, and
presses Enter.

```
uv run dojo test react v3rc03_accessibility_focus ex8
```

references.solution.tsx:
// v3rc03_accessibility_focus / ex8 - reference solution.
import { useEffect, useId, useMemo, useRef, useState } from "react";
import type { KeyboardEvent, ReactElement } from "react";

type Option = { id: string; label: string };

export function Combobox({
  label,
  options,
  onSelect,
}: {
  label: string;
  options: Option[];
  onSelect: (id: string) => void;
}): ReactElement {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);

  const baseId = useId();
  const inputId = `${baseId}-input`;
  const listId = `${baseId}-list`;
  const listRef = useRef<HTMLUListElement>(null);

  const filtered = useMemo(
    () => options.filter((o) => o.label.toLowerCase().includes(query.toLowerCase())),
    [options, query]
  );

  const active = open ? filtered[activeIndex] : undefined;

  // Focus never moves, so the browser has no reason to scroll anything. That
  // is the price of aria-activedescendant and it has to be paid explicitly.
  useEffect(() => {
    if (!active) return;
    listRef.current
      ?.querySelector(`#${CSS.escape(active.id)}`)
      ?.scrollIntoView({ block: "nearest" });
  }, [active]);

  function choose(option: Option) {
    onSelect(option.id);
    setQuery(option.label);
    setOpen(false);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      setOpen(true);
      setActiveIndex((i) => Math.min(i + 1, Math.max(filtered.length - 1, 0)));
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (event.key === "Enter") {
      if (active) {
        event.preventDefault();
        choose(active);
      }
    } else if (event.key === "Escape") {
      setOpen(false);
    }
  }

  return (
    <div>
      <label htmlFor={inputId}>{label}</label>
      <input
        id={inputId}
        type="text"
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-autocomplete="list"
        // Points at the active option's real id. DOM focus stays here, so
        // typing keeps working while the "cursor" moves through the list.
        aria-activedescendant={active?.id}
        value={query}
        onChange={(event) => {
          setQuery(event.target.value);
          setOpen(true);
          // The filtered list just changed; index 3 may now be a different
          // entry or none at all.
          setActiveIndex(0);
        }}
        onKeyDown={handleKeyDown}
      />
      {open && (
        <ul id={listId} role="listbox" ref={listRef}>
          {filtered.map((option, index) => (
            <li
              key={option.id}
              id={option.id}
              role="option"
              aria-selected={index === activeIndex}
              onMouseDown={(event) => {
                // mousedown, not click: click would blur the input first.
                event.preventDefault();
                choose(option);
              }}
            >
              {option.label}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

