import type { ReactElement } from "react";

export function SlidePanel({
  offset,
  faded,
}: {
  offset: number;
  faded: boolean;
}): ReactElement {
  return (
    <div
      data-testid="panel"
      style={{
        // transform and opacity only: the compositor can handle both without
        // layout or paint, and without the main thread.
        transform: `translateX(${offset * 200}px)`,
        opacity: faded ? 0.3 : 1,
        // The engine owns the interpolation. No frame loop, no per-frame
        // JavaScript, and it keeps running while the main thread is busy.
        transition: "transform 200ms ease-out, opacity 200ms ease-out",
      }}
    />
  );
}

