## Exercise 4 — a frame loop that stops

Edit `ex4/solution.tsx`. A progress ring driven by `requestAnimationFrame`.

Export:

```tsx
export function Ticker(props: {
  running: boolean;
  speed: number;                 // units per second
  onFrame: (value: number) => void;
}): ReactElement;
```

Requirements:

- while `running`, a `requestAnimationFrame` loop advances an internal value by
  `speed * deltaSeconds` each frame and calls `onFrame` with it;
- the value is rendered as `<span data-testid="value">{Math.floor(value)}</span>`
  — but the loop must not re-render the component on every frame; update the DOM
  node directly and re-render only when `running` flips;
- toggling `running` off cancels the frame; toggling it on resumes from where it
  stopped, without a jump caused by the paused time;
- unmounting cancels the frame;
- changing `speed` while running must take effect on the next frame **without**
  restarting the loop;
- it must be correct under StrictMode, where the effect mounts, cleans up, and
  mounts again.

The gate patches `requestAnimationFrame` and `cancelAnimationFrame`, runs a
handful of frames, toggles, changes speed, and unmounts, asserting no callback
runs after the final cancel.

```
uv run dojo test react v3rc04_animation_layout ex4
```

references.solution.tsx:
// v3rc04_animation_layout / ex4 - reference solution.
import { useEffect, useRef } from "react";
import type { ReactElement } from "react";

export function Ticker({
  running,
  speed,
  onFrame,
}: {
  running: boolean;
  speed: number;
  onFrame: (value: number) => void;
}): ReactElement {
  const spanRef = useRef<HTMLSpanElement>(null);
  const frameRef = useRef<number | null>(null);
  const valueRef = useRef(0);
  const lastRef = useRef<number | null>(null);

  // Read inside the loop instead of captured by it, so changing speed takes
  // effect next frame without tearing down and restarting the loop.
  const speedRef = useRef(speed);
  speedRef.current = speed;

  const onFrameRef = useRef(onFrame);
  onFrameRef.current = onFrame;

  useEffect(() => {
    if (!running) return;

    function step(now: number) {
      // A null "last" means this is the first frame after a start or resume;
      // using the pre-pause timestamp would produce one enormous delta.
      const delta = lastRef.current === null ? 0 : (now - lastRef.current) / 1000;
      lastRef.current = now;

      valueRef.current += speedRef.current * delta;
      if (spanRef.current) {
        // Written straight to the DOM: sixty renders a second for a number
        // only the user's eyes read would be pure waste.
        spanRef.current.textContent = String(Math.floor(valueRef.current));
      }
      onFrameRef.current(valueRef.current);

      frameRef.current = requestAnimationFrame(step);
    }

    frameRef.current = requestAnimationFrame(step);

    return () => {
      if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
      frameRef.current = null;
      // Reset so the next mount - including StrictMode's second one - starts
      // from a clean timestamp rather than resuming a stale delta.
      lastRef.current = null;
    };
  }, [running]);

  return <span ref={spanRef} data-testid="value">{Math.floor(valueRef.current)}</span>;
}

