Edit `ex6/solution.tsx`. Keep an element mounted long enough to animate away.

Export:

```tsx
export function useExit(show: boolean, durationMs: number): {
  mounted: boolean;
  state: "entering" | "shown" | "exiting";
};

export function Toast(props: {
  show: boolean;
  message: string;
  durationMs?: number;
}): ReactElement | null;
```

Requirements:

- when `show` goes false, `mounted` stays true for `durationMs` and `state`
  becomes `"exiting"`; then `mounted` becomes false;
- when `show` goes true again during the exit, the exit is cancelled and the
  element returns to `"shown"` without unmounting;
- `Toast` renders `null` when not mounted, and otherwise a
  `<div role="status" data-state={state}>` with `opacity` 1 when shown and 0
  when exiting, transitioned over `durationMs`;
- the removal must be driven by a timer, not by `transitionend` alone — but a
  `transitionend` on the element itself should remove it early if it arrives
  first;
- the pending timer must be cleared on unmount and whenever `show` changes.

The gate flips `show` off, advances fake timers to just under the duration and
asserts still mounted, advances past it and asserts unmounted; then repeats the
flip and turns `show` back on mid-exit, asserting the element never unmounted.

```
uv run dojo test react v3rc04_animation_layout ex6
```

references.solution.tsx:
// v3rc04_animation_layout / ex6 - reference solution.
import { useEffect, useState } from "react";
import type { ReactElement } from "react";

export function useExit(show: boolean, durationMs: number) {
  const [mounted, setMounted] = useState(show);
  const [state, setState] = useState<"entering" | "shown" | "exiting">(
    show ? "shown" : "exiting"
  );

  useEffect(() => {
    if (show) {
      // Coming back mid-exit: cancel by simply returning to the shown state.
      // The previous effect's cleanup already cleared the pending timer.
      setMounted(true);
      setState("shown");
      return;
    }
    if (!mounted) return;

    setState("exiting");
    // The timer is the mechanism, not the fallback: transitionend does not
    // fire for interrupted, never-started or backgrounded transitions.
    const id = setTimeout(() => setMounted(false), durationMs);
    return () => clearTimeout(id);
  }, [show, durationMs, mounted]);

  return { mounted, state };
}

export function Toast({
  show,
  message,
  durationMs = 200,
}: {
  show: boolean;
  message: string;
  durationMs?: number;
}): ReactElement | null {
  const { mounted, state } = useExit(show, durationMs);
  if (!mounted) return null;

  return (
    <div
      role="status"
      data-state={state}
      style={{
        opacity: state === "exiting" ? 0 : 1,
        transition: `opacity ${durationMs}ms ease-out`,
      }}
      onTransitionEnd={(event) => {
        // transitionend bubbles, so a transition on any child would otherwise
        // trigger this. Only act on our own element.
        if (event.target !== event.currentTarget) return;
      }}
    >
      {message}
    </div>
  );
}

