## Exercise 7 — measuring an element, not a window

Edit `ex7/solution.tsx`. Replace a `resize` listener with an observer.

Export:

```tsx
export function useElementSize<T extends HTMLElement>(): {
  ref: RefCallback<T>;
  size: { width: number; height: number } | null;
};

export function ResponsiveCard(props: {
  title: string;
  onLayout?: (mode: "narrow" | "wide") => void;
}): ReactElement;
```

Requirements:

- `useElementSize` observes the element it is attached to with a
  `ResizeObserver`, returning `null` until the first measurement;
- it must use a **ref callback**, not a ref object, so that it correctly
  re-observes when the node changes — including when it becomes `null` on
  unmount;
- exactly one observer per hook instance, disconnected on unmount;
- `ResponsiveCard` renders `data-mode="narrow"` below 400px and `"wide"` at 400
  and above, calling `onLayout` when the mode changes — not on every resize;
- the observer callback must not write any style that changes the observed
  element's size.

The gate replaces `ResizeObserver` with a controllable fake, fires resize
entries, asserts the mode flips at the boundary, asserts `onLayout` fired once
per mode change rather than once per entry, and asserts `disconnect` was called
on unmount.

```
uv run dojo test react v3rc04_animation_layout ex7
```

references.solution.tsx:
// v3rc04_animation_layout / ex7 - reference solution.
import { useCallback, useRef, useState } from "react";
import type { ReactElement, RefCallback } from "react";

export function useElementSize<T extends HTMLElement>() {
  const [size, setSize] = useState<{ width: number; height: number } | null>(null);
  const observerRef = useRef<ResizeObserver | null>(null);

  // A ref callback, not a ref object: it fires with the node on attach and
  // with null on detach, which is exactly the observer's lifecycle. An effect
  // keyed on a ref object would never re-run when the node changed.
  const ref: RefCallback<T> = useCallback((node) => {
    observerRef.current?.disconnect();
    observerRef.current = null;
    if (!node) return;

    const observer = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (!entry) return;
      // contentRect excludes padding and border; borderBoxSize includes them.
      // Pick one deliberately - mixing them is an off-by-padding bug.
      const { width, height } = entry.contentRect;
      setSize({ width, height });
    });
    observer.observe(node);
    observerRef.current = observer;
  }, []);

  return { ref, size };
}

export function ResponsiveCard({
  title,
  onLayout,
}: {
  title: string;
  onLayout?: (mode: "narrow" | "wide") => void;
}): ReactElement {
  const { ref, size } = useElementSize<HTMLDivElement>();
  const mode: "narrow" | "wide" = (size?.width ?? 0) >= 400 ? "wide" : "narrow";

  // Fire on transitions only. Calling from the observer callback would fire on
  // every entry, which during a drag is once per frame.
  const lastMode = useRef<"narrow" | "wide" | null>(null);
  if (size && lastMode.current !== mode) {
    lastMode.current = mode;
    queueMicrotask(() => onLayout?.(mode));
  }

  return (
    <div ref={ref} data-mode={mode}>
      <h3>{title}</h3>
    </div>
  );
}

