```

Requirements:

- `usePrefersReducedMotion` reports whether
  `(prefers-reduced-motion: reduce)` currently matches, and **re-renders when
  the user changes the setting while the page is open**;
- it must return `false` during server rendering rather than throwing;
- it must use `useSyncExternalStore`, and must add exactly one listener per
  subscription and remove it on unsubscribe;
- `Drawer` slides in with `transform: translateX()` over 250ms normally; under
  reduced motion it arrives at the final position immediately, but still
  cross-fades opacity over 100ms — the state change must not be cancelled, only
  the large motion;
- the drawer element carries `data-motion="full"` or `"reduced"`.

The gate installs a fake `matchMedia`, asserts the initial value, dispatches a
change event, and asserts the component re-rendered with the new value and that
the listener count returned to zero after unmount.

```
uv run dojo test react v3rc04_animation_layout ex8
```

references.solution.tsx:
// v3rc04_animation_layout / ex8 - reference solution.
import { useSyncExternalStore } from "react";
import type { ReactElement, ReactNode } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

// A boolean snapshot is stable by Object.is when nothing changed, which is what
// useSyncExternalStore requires; returning a fresh object here would loop.
function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export function Drawer({
  open,
  children,
}: {
  open: boolean;
  children: ReactNode;
}): ReactElement {
  const reduced = usePrefersReducedMotion();

  return (
    <div
      data-motion={reduced ? "reduced" : "full"}
      style={{
        // The state change is never cancelled - only the large motion is. A
        // short cross-fade is acceptable under reduced motion and still tells
        // the user that something happened.
        transform: open ? "translateX(0)" : "translateX(-100%)",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "opacity 100ms linear"
          : "transform 250ms ease-out, opacity 250ms ease-out",
      }}
    >
      {children}
    </div>
  );
}

