// v3rc04_animation_layout / challenge - reference solution.
import { useEffect, useId, useState } from "react";
import type { ReactElement, ReactNode } from "react";
import { usePrefersReducedMotion } from "./reduced-motion";

type Section = { id: string; title: string; body: ReactNode };

// Delayed unmount, as in ex6: the content must exist while the panel animates
// open or closed, and must be gone once it is fully closed.
function usePanelPresence(open: boolean, durationMs: number) {
  const [mounted, setMounted] = useState(open);

  useEffect(() => {
    if (open) {
      setMounted(true);
      return;
    }
    if (!mounted) return;
    const id = setTimeout(() => setMounted(false), durationMs);
    return () => clearTimeout(id);
  }, [open, durationMs, mounted]);

  return mounted;
}

function Panel({
  id,
  labelledBy,
  open,
  durationMs,
  children,
}: {
  id: string;
  labelledBy: string;
  open: boolean;
  durationMs: number;
  children: ReactNode;
}): ReactElement | null {
  const reduced = usePrefersReducedMotion();
  const mounted = usePanelPresence(open, reduced ? 0 : durationMs);

  if (!mounted) return null;

  return (
    <div
      id={id}
      role="region"
      aria-labelledby={labelledBy}
      data-open={open}
      style={{
        display: "grid",
        // A grid row interpolates between fractions, which is how this
        // animates without ever knowing the content's height. Failure mode of
        // the alternatives: a guessed max-height animates through empty space,
        // and a measured pixel height stops the panel growing later.
        gridTemplateRows: open ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows ${durationMs}ms ease-out`,
      }}
    >
      <div
        style={{
          // Both required. Grid items default to min-height: auto, which
          // refuses to shrink below their content and silently defeats the
          // whole technique.
          overflow: "hidden",
          minHeight: 0,
        }}
      >
        {children}
      </div>
    </div>
  );
}

export function Accordion({
  sections,
  durationMs = 220,
}: {
  sections: Section[];
  durationMs?: number;
}): ReactElement {
  const [openIds, setOpenIds] = useState<Set<string>>(new Set());
  const baseId = useId();

  function toggle(id: string) {
    setOpenIds((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  return (
    <div>
      {sections.map((section) => {
        const open = openIds.has(section.id);
        const triggerId = `${baseId}-${section.id}-trigger`;
        const panelId = `${baseId}-${section.id}-panel`;
        return (
          <div key={section.id}>
            <button
              type="button"
              id={triggerId}
              aria-expanded={open}
              aria-controls={panelId}
              onClick={() => toggle(section.id)}
            >
              {section.title}
            </button>
            <Panel
              id={panelId}
              labelledBy={triggerId}
              open={open}
              durationMs={durationMs}
            >
              {section.body}
            </Panel>
          </div>
        );
      })}
    </div>
  );
}

// v3rc04_animation_layout / review1 - reference solution.
import { useEffect, useLayoutEffect, useRef } from "react";
import type { ReactElement } from "react";

export const CAUSES: string[] = [
  "Animating style.left invalidates layout, so every frame runs style, layout, paint and composite on the main thread; transform is compositor-only and can run while the main thread is busy.",
  "Reading getBoundingClientRect() and writing a style in the same loop iteration forces a synchronous layout per point, because each write dirties the layout the next read must resolve; batching all reads before all writes costs one layout for the whole pass.",
  "The requestAnimationFrame loop was started with no cleanup, so it kept scheduling itself after unmount - wasted frames forever, and the callback closure holds the whole component alive.",
];

type Point = { id: string; x: number; label: string };

export function Sparkline({
  points,
  markerX,
  animating,
}: {
  points: Point[];
  markerX: number;
  animating: boolean;
}): ReactElement {
  const markerRef = useRef<HTMLDivElement>(null);
  const labelRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const frameRef = useRef<number | null>(null);
  const markerXRef = useRef(markerX);
  markerXRef.current = markerX;

  // Cause 2 fixed: one read pass, then one write pass, so the whole labelling
  // costs a single forced layout instead of one per point.
  useLayoutEffect(() => {
    const nodes = labelRefs.current.filter((n): n is HTMLSpanElement => n !== null);
    const rects = nodes.map((node) => node.getBoundingClientRect());
    nodes.forEach((node, index) => {
      const offset = points[index].x - rects[index].width / 2;
      node.style.transform = `translateX(${offset}px)`;
    });
  }, [points]);

  // Cause 3 fixed: the effect cancels the pending frame on cleanup, so the
  // loop stops on unmount and whenever `animating` goes false.
  useEffect(() => {
    if (!animating) return;

    function step() {
      if (markerRef.current) {
        // Cause 1 fixed: a transform, handled by the compositor, rather than
        // `left`, which invalidates layout every frame.
        markerRef.current.style.transform = `translateX(${markerXRef.current}px)`;
      }
      frameRef.current = requestAnimationFrame(step);
    }

    frameRef.current = requestAnimationFrame(step);
    return () => {
      if (frameRef.current !== null) cancelAnimationFrame(frameRef.current);
      frameRef.current = null;
    };
  }, [animating]);

  return (
    <div style={{ position: "relative" }}>
      <div
        ref={markerRef}
        data-testid="marker"
        style={{ position: "absolute", left: 0, top: 0 }}
      />
      {points.map((point, index) => (
        <span
          key={point.id}
          ref={(node) => {
            labelRefs.current[index] = node;
          }}
          style={{ position: "absolute", left: 0 }}
        >
          {point.label}
        </span>
      ))}
    </div>
  );
}

