// v3rc05_routing_url_state / ex1 - reference solution.
import { useSyncExternalStore } from "react";
import type { ReactElement } from "react";
import { subscribeToLocation } from "./location-store";

export function useSearchParam(key: string): string | null {
  // The snapshot is a string, which is Object.is-stable when nothing changed.
  // Returning `new URLSearchParams(...)` here would be a fresh object every
  // call and React would re-render forever.
  const search = useSyncExternalStore(
    subscribeToLocation,
    () => window.location.search,
    () => ""
  );

  // Parsed during render from the current URL. No state, no effect, no copy -
  // so there is nothing that can drift when the user presses Back.
  return new URLSearchParams(search).get(key);
}

export function StatusBadge(): ReactElement {
  const status = useSearchParam("status");
  // `null` means absent; "" means `?status=`, which is an explicit empty
  // filter and a different thing. `!status` would conflate them.
  return <p>Status: {status === null ? "any" : status}</p>;
}

