// v3rc05_routing_url_state / ex2 - reference solution.
import { useId } from "react";
import type { ReactElement } from "react";
import { useSearchParam } from "./use-search-param";

export function setSearchParam(
  key: string,
  value: string | null,
  mode: "push" | "replace"
): void {
  // Start from the whole current URL so path, hash and every other parameter
  // survive. Rebuilding from pathname + your own params silently drops them.
  const url = new URL(window.location.href);

  if (value === null || value === "") {
    // `set(key, "")` would leave `?q=`, which reads back as an empty string -
    // an active filter matching everything, not an absent one.
    url.searchParams.delete(key);
  } else {
    // Encoding is handled by the API. Hand-built query strings turn a value of
    // "a&b=c" into two parameters.
    url.searchParams.set(key, value);
  }

  // Passing history.state through keeps whatever this entry was carrying.
  if (mode === "push") history.pushState(history.state, "", url);
  else history.replaceState(history.state, "", url);
}

export function FilterBar({
  onNavigate,
}: {
  onNavigate?: (href: string) => void;
}): ReactElement {
  const status = useSearchParam("status") ?? "any";
  const query = useSearchParam("q") ?? "";
  const baseId = useId();

  function write(key: string, value: string | null, mode: "push" | "replace") {
    setSearchParam(key, value, mode);
    onNavigate?.(window.location.href);
  }

  return (
    <div>
      <label htmlFor={`${baseId}-status`}>Status</label>
      <select
        id={`${baseId}-status`}
        value={status}
        // A discrete choice: Back should restore the previous choice.
        onChange={(event) =>
          write("status", event.target.value === "any" ? null : event.target.value, "push")
        }
      >
        <option value="any">any</option>
        <option value="paid">paid</option>
        <option value="unpaid">unpaid</option>
      </select>

      <label htmlFor={`${baseId}-q`}>Search</label>
      <input
        id={`${baseId}-q`}
        type="search"
        value={query}
        // A continuous adjustment: pushing here would give one history entry
        // per keystroke and a back button that retypes the query backwards.
        onChange={(event) => write("q", event.target.value, "replace")}
      />
    </div>
  );
}

// v3rc05_routing_url_state / ex3 - reference solution.
import { useMemo, useSyncExternalStore } from "react";

const listeners = new Set<() => void>();

let originalPushState: typeof history.pushState | null = null;
let originalReplaceState: typeof history.replaceState | null = null;

function emit() {
  for (const listener of [...listeners]) listener();
}

function install() {
  if (originalPushState) return;

  originalPushState = history.pushState;
  originalReplaceState = history.replaceState;

  // pushState and replaceState fire no event of their own, so a store built
  // only on popstate sees the user's navigations and misses the app's.
  history.pushState = function (...args) {
    // apply(this, ...) keeps `this` bound to the history object; the native
    // method requires it.
    const result = originalPushState!.apply(this, args);
    emit();
    return result;
  };
  history.replaceState = function (...args) {
    const result = originalReplaceState!.apply(this, args);
    emit();
    return result;
  };

  window.addEventListener("popstate", emit);
}

function uninstall() {
  if (!originalPushState) return;
  history.pushState = originalPushState;
  history.replaceState = originalReplaceState!;
  originalPushState = null;
  originalReplaceState = null;
  window.removeEventListener("popstate", emit);
}

export function subscribeToLocation(onChange: () => void): () => void {
  // Reference counted: one patch for the module however many components
  // subscribe, restored when the last one leaves.
  if (listeners.size === 0) install();
  listeners.add(onChange);

  return () => {
    listeners.delete(onChange);
    if (listeners.size === 0) uninstall();
  };
}

// A string snapshot: Object.is-stable, so React only re-renders on real change.
export function getLocationSnapshot(): string {
  return window.location.href;
}

function getServerSnapshot(): string {
  return "http://localhost/";
}

export function useLocation() {
  const href = useSyncExternalStore(
    subscribeToLocation,
    getLocationSnapshot,
    getServerSnapshot
  );
  // Parsed downstream of the snapshot, so the object identity churn happens
  // here - where a memo can contain it - rather than inside getSnapshot.
  return useMemo(() => {
    const url = new URL(href);
    return { pathname: url.pathname, search: url.search, hash: url.hash };
  }, [href]);
}

// v3rc05_routing_url_state / ex4 - reference solution.
const stripTrailing = (value: string): string => value.replace(/\/+$/, "");

export function matchPath(
  pattern: string,
  pathname: string
): Record<string, string> | null {
  // Normalised identically, so a trailing slash on either side is
  // insignificant. "/" becomes "" and splits to [""] on both sides.
  const patternSegments = stripTrailing(pattern).split("/");
  const pathSegments = stripTrailing(pathname).split("/");

  const params: Record<string, string> = {};

  for (let i = 0; i < patternSegments.length; i++) {
    const expected = patternSegments[i];

    if (expected === "*") {
      // The one case where the lengths legitimately differ. At least one
      // segment must remain, so /docs does not match /docs/*.
      const rest = pathSegments.slice(i);
      if (rest.length === 0 || rest.every((segment) => segment === "")) return null;
      params["*"] = rest.join("/");
      return params;
    }

    const actual = pathSegments[i];
    if (actual === undefined) return null;

    if (expected.startsWith(":")) {
      // A parameter never matches an empty segment: /files/ is not a file.
      if (actual === "") return null;
      // Decoded AFTER splitting. Decoding first would turn an encoded slash
      // (%2F) into a real one and match a different route entirely.
      params[expected.slice(1)] = decodeURIComponent(actual);
    } else if (expected !== actual) {
      // Case-sensitive: paths are, by specification, and treating them
      // otherwise gives the same page infinitely many URLs.
      return null;
    }
  }

  // Extra trailing segments in the path are not a match.
  if (pathSegments.length !== patternSegments.length) return null;

  // `{}` here means "matched, captured nothing" - a different answer from the
  // `null` that means "did not match".
  return params;
}

