// v3rc05_routing_url_state / ex5 - reference solution.
import { useId } from "react";
import type { ReactElement } from "react";
import { useLocation } from "./location-store";

export function useParamSet(key: string) {
  const { search } = useLocation();
  // getAll, not get: `get` returns only the first value, which is how a
  // multi-select silently becomes a single-select.
  const values = new URLSearchParams(search).getAll(key);

  function write(next: string[]) {
    const url = new URL(window.location.href);
    // Delete then append: `set` would replace every occurrence with one value.
    url.searchParams.delete(key);
    // Sorted, so the same logical set always produces the same URL string -
    // which matters for cache keys, for comparing links, and for tests.
    for (const value of [...next].sort()) url.searchParams.append(key, value);
    // An empty `next` leaves the key deleted, so `?tags=` never appears.
    history.pushState(history.state, "", url);
  }

  return {
    values,
    toggle(value: string) {
      const index = values.indexOf(value);
      const next =
        index === -1
          ? [...values, value]
          : [...values.slice(0, index), ...values.slice(index + 1)];
      write(next);
    },
    clear() {
      write([]);
    },
  };
}

export function TagFilter({ allTags }: { allTags: string[] }): ReactElement {
  const { values, toggle } = useParamSet("tags");
  const baseId = useId();
  const selected = new Set(values);

  return (
    <fieldset>
      <legend>Tags</legend>
      {allTags.map((tag) => {
        const id = `${baseId}-${tag}`;
        return (
          <div key={tag}>
            <input
              id={id}
              type="checkbox"
              checked={selected.has(tag)}
              onChange={() => toggle(tag)}
            />
            <label htmlFor={id}>{tag}</label>
          </div>
        );
      })}
    </fieldset>
  );
}

