// v3rc05_routing_url_state / ex6 - reference solution.
import type { ReactElement, ReactNode } from "react";
import { matchPath } from "./match-path";

export type RouteDef = {
  path: string;
  element: (props: { params: Record<string, string>; outlet: ReactNode }) => ReactNode;
  children?: RouteDef[];
};

type Matched = { route: RouteDef; params: Record<string, string> };

const join = (parent: string, child: string): string =>
  child === "" ? parent : `${parent.replace(/\/+$/, "")}/${child.replace(/^\/+/, "")}`;

// Pass one: walk the tree and produce the chain of matched routes plus the
// accumulated parameters. Returns null when nothing matches.
function matchChain(
  routes: RouteDef[],
  pathname: string,
  parentPath: string,
  inherited: Record<string, string>
): Matched[] | null {
  for (const route of routes) {
    const full = join(parentPath, route.path);

    if (route.children?.length) {
      for (const child of route.children) {
        const childFull = join(full, child.path);
        const params = matchPath(childFull, pathname);
        if (!params) continue;
        const merged = { ...inherited, ...params };
        // Child params win over the parent's on a name collision - they are
        // nearer. Better still: name them distinctly and never collide.
        const deeper = child.children?.length
          ? matchChain([child], pathname, full, merged)
          : [{ route: child, params: merged }];
        if (deeper) return [{ route, params: merged }, ...deeper];
      }
    }

    const params = matchPath(full, pathname);
    if (params) return [{ route, params: { ...inherited, ...params } }];
  }
  return null;
}

export function Routes({
  routes,
  pathname,
}: {
  routes: RouteDef[];
  pathname: string;
}): ReactElement | null {
  const chain = matchChain(routes, pathname, "", {});
  if (!chain) return null;

  // Pass two: fold from the inside out, so each level already has its child in
  // hand to pass as the outlet.
  let outlet: ReactNode = null;
  for (let i = chain.length - 1; i >= 0; i--) {
    const { route, params } = chain[i];
    outlet = route.element({ params, outlet });
  }

  // No key derived from the pathname anywhere: React preserves a component
  // instance when it sees the same type at the same position, which is exactly
  // what keeps a layout's state alive across sibling navigations.
  return <>{outlet}</>;
}

