// v3rc05_routing_url_state / ex7 - reference solution.
import { Suspense, lazy, useEffect } from "react";
import type { ComponentType, LazyExoticComponent, ReactElement, ReactNode } from "react";

// Module scope, so the import promise is cached once. Calling lazy() inside a
// render produces a new component with a new cache every time, and the
// fallback never goes away.
export const LazySettings: LazyExoticComponent<ComponentType> = lazy(
  () => import("./settings-page")
);

export function RequireAuth({
  user,
  redirectTo,
  children,
  onRedirect,
}: {
  user: { id: string } | null;
  redirectTo: string;
  children: ReactNode;
  onRedirect?: (to: string) => void;
}): ReactElement {
  const blocked = user === null;

  useEffect(() => {
    if (!blocked) return;
    history.replaceState(null, "", redirectTo);
    onRedirect?.(redirectTo);
  }, [blocked, redirectTo, onRedirect]);

  // Decided during render. Doing this only in the effect would render, commit
  // and paint the protected page first - and run its effects, which means its
  // requests. `children` being an element is not the same as rendering it:
  // React only calls the component if it appears in the returned tree.
  if (blocked) return <p role="status">Redirecting…</p>;

  return <>{children}</>;
}

export function SettingsRoute({
  user,
}: {
  user: { id: string } | null;
}): ReactElement {
  return (
    <RequireAuth user={user} redirectTo="/login">
      {/* Suspense inside the guard: an unauthorised visitor never sees a
          loading state for a page they will not be given. */}
      <Suspense fallback={<p role="status">Loading settings…</p>}>
        <LazySettings />
      </Suspense>
    </RequireAuth>
  );
}

