// v3rc05_routing_url_state / ex8 - reference solution.
import { useEffect, useLayoutEffect, useRef } from "react";
import type { ReactElement, ReactNode } from "react";
import { useLocation } from "./location-store";

export function useScrollRestoration(): void {
  const { pathname, search } = useLocation();
  const key = `${pathname}${search}`;

  useEffect(() => {
    // The browser's own guess has no idea when a pushState navigation's
    // content is ready, so turn it off rather than fight it.
    const previous = history.scrollRestoration;
    history.scrollRestoration = "manual";
    return () => {
      history.scrollRestoration = previous;
    };
  }, []);

  useEffect(() => {
    // Save on the way out. Attached to the history entry rather than keyed by
    // path: the same path visited twice can have two different positions.
    function save() {
      history.replaceState({ ...history.state, scrollY: window.scrollY }, "");
    }
    window.addEventListener("beforeunload", save);
    return () => {
      save();
      window.removeEventListener("beforeunload", save);
    };
  }, [key]);

  useLayoutEffect(() => {
    // After the new view committed, before paint. Earlier and the document is
    // still the old height, so the browser clamps the offset.
    const saved = (history.state as { scrollY?: number } | null)?.scrollY;
    window.scrollTo(0, typeof saved === "number" ? saved : 0);
  }, [key]);
}

export function RouteView({
  heading,
  children,
}: {
  heading: string;
  children: ReactNode;
}): ReactElement {
  const { pathname, search } = useLocation();
  const headingRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    // preventScroll, or focusing the heading scrolls it into view and
    // immediately undoes the restoration above.
    headingRef.current?.focus({ preventScroll: true });
  }, [pathname, search]);

  return (
    <div>
      {/* tabIndex -1: focusable by script, absent from the tab order. */}
      <h1 ref={headingRef} tabIndex={-1}>
        {heading}
      </h1>
      {children}
    </div>
  );
}

