// v3rc05_routing_url_state / challenge - reference solution.
import { useId, useMemo } from "react";
import type { ReactElement } from "react";
import { useLocation } from "./location-store";

export type ListState = {
  q: string;
  tags: string[];
  sort: "name" | "date";
  dir: "asc" | "desc";
  page: number;
};

const DEFAULTS: ListState = { q: "", tags: [], sort: "name", dir: "asc", page: 1 };

const SORTS = new Set(["name", "date"]);
const DIRS = new Set(["asc", "desc"]);

// Total by construction: every unexpected input falls back to a default rather
// than throwing. URLs are hand-edited, truncated by chat clients and produced
// by older versions of this code.
export function parseListState(search: string): ListState {
  const params = new URLSearchParams(search);

  const rawSort = params.get("sort");
  const rawDir = params.get("dir");
  const rawPage = Number(params.get("page"));

  return {
    q: params.get("q") ?? DEFAULTS.q,
    tags: params.getAll("tags"),
    sort: rawSort && SORTS.has(rawSort) ? (rawSort as ListState["sort"]) : DEFAULTS.sort,
    dir: rawDir && DIRS.has(rawDir) ? (rawDir as ListState["dir"]) : DEFAULTS.dir,
    // Number("banana") is NaN and NaN < 1 is false, so a bare clamp lets it
    // through. Check integrality explicitly.
    page: Number.isInteger(rawPage) && rawPage >= 1 ? rawPage : DEFAULTS.page,
  };
}

// Defaults are omitted, so a default view has an empty query string and
// parse(serialise(x)) round-trips to x.
export function serialiseListState(state: ListState): string {
  const params = new URLSearchParams();
  if (state.q !== DEFAULTS.q) params.set("q", state.q);
  for (const tag of [...state.tags].sort()) params.append("tags", tag);
  if (state.sort !== DEFAULTS.sort) params.set("sort", state.sort);
  if (state.dir !== DEFAULTS.dir) params.set("dir", state.dir);
  if (state.page !== DEFAULTS.page) params.set("page", String(state.page));
  const query = params.toString();
  return query ? `?${query}` : "";
}

export function InvoiceList({
  invoices,
  pageSize = 10,
}: {
  invoices: { id: string; name: string; date: string; tags: string[] }[];
  pageSize?: number;
}): ReactElement {
  const { search } = useLocation();
  const state = parseListState(search);
  const baseId = useId();

  // One writer for the whole state. Five separate setters would force the
  // page-reset rule to run as a second write, producing a history entry for a
  // state the user was never in.
  function update(patch: Partial<ListState>, mode: "push" | "replace") {
    const current = parseListState(window.location.search);
    const resetsPage = "q" in patch || "tags" in patch || "sort" in patch;
    const next: ListState = {
      ...current,
      ...patch,
      ...(resetsPage ? { page: 1 } : null),
    };
    const url = new URL(window.location.href);
    url.search = serialiseListState(next);
    if (mode === "push") history.pushState(history.state, "", url);
    else history.replaceState(history.state, "", url);
  }

  const visible = useMemo(() => {
    const needle = state.q.toLowerCase();
    const wanted = new Set(state.tags);
    const filtered = invoices.filter(
      (invoice) =>
        invoice.name.toLowerCase().includes(needle) &&
        (wanted.size === 0 || invoice.tags.some((tag) => wanted.has(tag)))
    );
    const factor = state.dir === "asc" ? 1 : -1;
    // Copied before sorting: sorting a prop rewrites the caller's array.
    return [...filtered].sort(
      (a, b) => factor * (state.sort === "name" ? a.name.localeCompare(b.name) : a.date.localeCompare(b.date))
    );
  }, [invoices, state.q, state.tags, state.sort, state.dir]);

  const pageCount = Math.max(1, Math.ceil(visible.length / pageSize));
  const page = Math.min(state.page, pageCount);
  const rows = visible.slice((page - 1) * pageSize, page * pageSize);

  function toggleSort(key: ListState["sort"]) {
    if (state.sort === key) update({ dir: state.dir === "asc" ? "desc" : "asc" }, "push");
    else update({ sort: key }, "push");
  }

  return (
    <div>
      <label htmlFor={`${baseId}-q`}>Search</label>
      <input
        id={`${baseId}-q`}
        type="search"
        value={state.q}
        // Continuous adjustment: replace, or one entry per keystroke.
        onChange={(event) => update({ q: event.target.value }, "replace")}
      />

      <button type="button" onClick={() => toggleSort("name")}>
        Sort by name
      </button>
      <button type="button" onClick={() => toggleSort("date")}>
        Sort by date
      </button>

      <ul>
        {rows.map((invoice) => (
          <li key={invoice.id}>{invoice.name}</li>
        ))}
      </ul>

      <p>
        Page {page} of {pageCount}
      </p>
      <button
        type="button"
        disabled={page <= 1}
        onClick={() => update({ page: page - 1 }, "push")}
      >
        Previous
      </button>
      <button
        type="button"
        disabled={page >= pageCount}
        onClick={() => update({ page: page + 1 }, "push")}
      >
        Next
      </button>
    </div>
  );
}

