    await waitForElementToBeRemoved(() => screen.queryByRole("status"));
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
  });

  it("shows an alert and no name when the request fails", async () => {
    mockProfile("1", Promise.reject(new Error("boom")));
    render(<UserCard userId="1" />);

    // Wait for the error state to exist, then assert the success state does
    // not - "never appears" is not something you can wait for.
    expect(await screen.findByRole("alert")).toHaveTextContent(/could not/i);
    expect(screen.queryByRole("heading")).not.toBeInTheDocument();
  });
});

