// v3rc06_testing_like_users / ex4 - reference solution.
import { render, screen } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { setupServer } from "msw/node";
import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
import { InvoiceTable } from "./invoice-table";

const server = setupServer(
  http.get("/api/invoices", () =>
    HttpResponse.json([{ id: "1", amount: 1250, ref: "INV-1" }])
  )
);

// onUnhandledRequest: "error" - a request with no handler fails loudly instead
// of hanging and timing out somewhere unrelated.
beforeAll(() => server.listen({ onUnhandledRequest: "error" }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

describe("InvoiceTable", () => {
  it("renders a row per invoice with the formatted amount", async () => {
    render(<InvoiceTable />);

    // Intercepting at the network boundary leaves the component's own parsing
    // and formatting under test - which is where the bugs live.
    const rows = await screen.findAllByRole("row");
    expect(rows).toHaveLength(2); // header + one invoice
    expect(rows[1]).toHaveTextContent("£12.50");
  });

  it("shows an alert for a 500", async () => {
    server.use(
      http.get("/api/invoices", () => new HttpResponse(null, { status: 500 }))
    );
    render(<InvoiceTable />);

    expect(await screen.findByRole("alert")).toHaveTextContent(/could not load/i);
  });

  it("shows an alert for malformed JSON", async () => {
    // response.json() rejects here. A component that only checks response.ok
    // throws an unhandled rejection, which is the bug this case catches.
    server.use(
      http.get("/api/invoices", () =>
        new HttpResponse("{not json", { headers: { "Content-Type": "application/json" } })
      )
    );
    render(<InvoiceTable />);

    expect(await screen.findByRole("alert")).toHaveTextContent(/could not load/i);
  });

  it("asks for JSON", async () => {
    let seen: Request | null = null;
    server.use(
      http.get("/api/invoices", ({ request }) => {
        seen = request;
        return HttpResponse.json([]);
      })
    );
    render(<InvoiceTable />);

    await screen.findByRole("table");
    expect(seen?.headers.get("Accept")).toBe("application/json");
  });
});

// v3rc06_testing_like_users / ex5 - reference solution.
import { act, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { SearchBox } from "./search-box";

const DELAY = 300;

beforeEach(() => vi.useFakeTimers());
// Paired, always. A leaked fake clock hangs unrelated test files in the same
// worker, which is a miserable thing to debug.
afterEach(() => vi.useRealTimers());

function setup() {
  // Without advanceTimers, userEvent's internal waits use frozen real timers
  // and the test HANGS rather than failing.
  const user = userEvent.setup({ advanceTimers: vi.advanceTimersByTime });
  const onSearch = vi.fn();
  render(<SearchBox onSearch={onSearch} delayMs={DELAY} />);
  return { user, onSearch };
}

describe("SearchBox", () => {
  it("does not fire before the delay elapses", async () => {
    const { user, onSearch } = setup();

    await user.type(screen.getByRole("searchbox"), "react");
    act(() => {
      vi.advanceTimersByTime(DELAY - 1);
    });

    // Asserting an absence at a moment in time is the case fake timers exist
    // for - you cannot wait for something not to happen.
    expect(onSearch).not.toHaveBeenCalled();
  });

  it("fires once after the delay", async () => {
    const { user, onSearch } = setup();

    await user.type(screen.getByRole("searchbox"), "react");
    // act, because this update originates from a timer rather than from a user
    // interaction - one of the few places writing it yourself is correct.
    act(() => {
      vi.advanceTimersByTime(DELAY);
    });

    expect(onSearch).toHaveBeenCalledTimes(1);
    expect(onSearch).toHaveBeenLastCalledWith("react");
  });

  it("resets the timer rather than accumulating", async () => {
    const { user, onSearch } = setup();
    const box = screen.getByRole("searchbox");

    await user.type(box, "react");
    act(() => vi.advanceTimersByTime(DELAY));
    await user.type(box, "ive");
    act(() => vi.advanceTimersByTime(DELAY));

    // A debounce that forgets to clear its previous timeout passes both tests
    // above and fails this one, firing once per keystroke.
    expect(onSearch).toHaveBeenCalledTimes(2);
    expect(onSearch).toHaveBeenNthCalledWith(1, "react");
    expect(onSearch).toHaveBeenNthCalledWith(2, "reactive");
  });
});

