// v3rc06_testing_like_users / ex6 - reference solution.
import { act, render, renderHook, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, describe, expect, it } from "vitest";
import { useLocalStorage } from "./use-local-storage";
import { useSelection } from "./use-selection";

export const WHY: string =
  "useSelection's contract is with the UI, so a host component exercises the real thing including re-renders; useLocalStorage's whole observable surface is its return value and a browser API, so a host component would just be JSON.stringify of result.current.";

// --- useSelection: through a disposable host -----------------------------

function SelectionHost({ items }: { items: string[] }) {
  const { selected, toggle, clear } = useSelection(items);
  return (
    <div>
      {items.map((item) => (
        <label key={item}>
          <input
            type="checkbox"
            checked={selected.includes(item)}
            onChange={() => toggle(item)}
          />
          {item}
        </label>
      ))}
      <button type="button" onClick={clear}>
        Clear
      </button>
    </div>
  );
}

describe("useSelection", () => {
  it("toggles items independently and clears them all", async () => {
    const user = userEvent.setup();
    render(<SelectionHost items={["a", "b", "c"]} />);

    await user.click(screen.getByLabelText("a"));
    await user.click(screen.getByLabelText("b"));

    // Read through the UI, never through result.current: this asserts the
    // behaviour that ships rather than the hook's internal return value.
    expect(screen.getByLabelText("a")).toBeChecked();
    expect(screen.getByLabelText("b")).toBeChecked();
    expect(screen.getByLabelText("c")).not.toBeChecked();

    await user.click(screen.getByLabelText("a"));
    expect(screen.getByLabelText("a")).not.toBeChecked();
    expect(screen.getByLabelText("b")).toBeChecked();

    await user.click(screen.getByRole("button", { name: /clear/i }));
    for (const item of ["a", "b", "c"]) {
      expect(screen.getByLabelText(item)).not.toBeChecked();
    }
  });
});

// --- useLocalStorage: renderHook is the honest tool ----------------------

describe("useLocalStorage", () => {
  beforeEach(() => localStorage.clear());

  it("reads an existing value on mount", () => {
    localStorage.setItem("theme", JSON.stringify("dark"));
    const { result } = renderHook(() => useLocalStorage("theme", "light"));
    expect(result.current[0]).toBe("dark");
  });

  it("writes through on update", () => {
    const { result } = renderHook(() => useLocalStorage("theme", "light"));
    // State updates outside a user interaction need act.
    act(() => result.current[1]("dark"));
    expect(result.current[0]).toBe("dark");
    expect(localStorage.getItem("theme")).toBe(JSON.stringify("dark"));
  });

  it("follows a changed key", () => {
    localStorage.setItem("a", JSON.stringify(1));
    localStorage.setItem("b", JSON.stringify(2));

    const { result, rerender } = renderHook(({ key }) => useLocalStorage(key, 0), {
      initialProps: { key: "a" },
    });
    expect(result.current[0]).toBe(1);

    // rerender is the only way to catch "captured on first render and never
    // updated", which is a whole class of hook bug.
    rerender({ key: "b" });
    expect(result.current[0]).toBe(2);
  });
});

// v3rc06_testing_like_users / ex7 - reference solution.
import { useId, useState } from "react";
import type { ReactElement, ReactNode } from "react";

export function Accordion({
  title,
  children,
}: {
  title: string;
  children: ReactNode;
}): ReactElement {
  const [open, setOpen] = useState(false);
  const baseId = useId();
  const triggerId = `${baseId}-trigger`;
  const panelId = `${baseId}-panel`;

  return (
    <div>
      {/* A real button: Enter and Space activation, the tab stop, the role and
          the focus ring all arrive together. Needing an onKeyDown for Enter is
          the sign the element underneath is wrong. */}
      <button
        type="button"
        id={triggerId}
        // The state is now published where the user's assistive technology can
        // see it, which is also where a test can see it. The class was only
        // ever telling the stylesheet.
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        onClick={() => setOpen((current) => !current)}
      >
        {title}
      </button>

      {open && (
        <div
          id={panelId}
          role="region"
          aria-labelledby={triggerId}
          // Kept for styling. Nothing depends on it, so renaming it breaks
          // nothing but the CSS.
          className="panel is-open"
        >
          {children}
        </div>
      )}
    </div>
  );
}

