// v3rc06_testing_like_users / ex8 - reference solution.
import { useEffect, useState } from "react";
import type { ReactElement } from "react";
import { fetchStatus } from "./fetch-status";

export function PollingStatus({
  endpoint,
  intervalMs,
  onStatus,
}: {
  endpoint: string;
  intervalMs: number;
  onStatus?: (status: string) => void;
}): ReactElement {
  const [status, setStatus] = useState("unknown");

  useEffect(() => {
    // Scoped to this run of the effect, so a re-run - including StrictMode's
    // second mount - gets its own flag and cannot be confused by the first.
    let alive = true;

    function apply(next: string) {
      // A promise cannot be cancelled, only ignored. The guard is not there to
      // silence a warning; it is there because the work should have stopped.
      if (!alive) return;
      setStatus(next);
      onStatus?.(next);
    }

    // The one-off fetch on mount.
    fetchStatus(endpoint).then(apply, () => {});

    // The poll. Its closure is recreated whenever endpoint changes, because
    // endpoint is in the dependency array - which fixes the stale-endpoint
    // defect and the never-restarts defect with the same line.
    const id = setInterval(() => {
      fetchStatus(endpoint).then(apply, () => {});
    }, intervalMs);

    return () => {
      alive = false;
      // Every setInterval needs a matching clearInterval. Without it the poll
      // outlives the component, holding its whole closure alive and issuing
      // requests for a screen the user has left.
      clearInterval(id);
    };
  }, [endpoint, intervalMs, onStatus]);

  return <p role="status">{status}</p>;
}

