import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import { Combobox } from "./combobox";
import { mockOptions } from "./mock-options";

const CITIES = [
  { id: "opt-oslo", label: "Oslo" },
  { id: "opt-boston", label: "Boston" },
  { id: "opt-lisbon", label: "Lisbon" },
  { id: "opt-cairo", label: "Cairo" },
];

function setup() {
  const user = userEvent.setup();
  const onSelect = vi.fn();
  mockOptions(CITIES);
  render(<Combobox label="City" onSelect={onSelect} />);
  return { user, onSelect, input: screen.getByRole("combobox", { name: /city/i }) };
}

describe("Combobox", () => {
  it("starts collapsed with no listbox", () => {
    const { input } = setup();
    expect(input).toHaveAttribute("aria-expanded", "false");
    expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
  });

  it("opens and filters as the user types", async () => {
    const { user, input } = setup();

    await user.type(input, "os");

    // findAll once, at the point the options first have to exist. After this
    // the list is present and getAll is correct - findAll everywhere would
    // hide which assertion is the asynchronous one.
    const options = await screen.findAllByRole("option");
    expect(options.map((o) => o.textContent)).toEqual(["Oslo", "Boston"]);
    expect(input).toHaveAttribute("aria-expanded", "true");
  });

  it("moves the active option without moving DOM focus", async () => {
    const { user, input } = setup();

    await user.type(input, "o");
    const options = await screen.findAllByRole("option");
    await user.keyboard("{ArrowDown}{ArrowDown}");

    // The load-bearing pair. `expect(options[1]).toHaveFocus()` would be wrong
    // AND would pass against a broken implementation that moved real focus -
    // at which point typing would stop working.
    expect(input).toHaveFocus();
    expect(input).toHaveAttribute("aria-activedescendant", options[1].id);
    // A dangling activedescendant is silently ignored by assistive technology,
    // so check the target actually exists.
    expect(document.getElementById(options[1].id)).toBeInTheDocument();
  });

  it("marks exactly one option as selected", async () => {
    const { user, input } = setup();

    await user.type(input, "o");
    await screen.findAllByRole("option");
    await user.keyboard("{ArrowDown}");

    const selected = screen.getAllByRole("option", { selected: true });
    expect(selected).toHaveLength(1);
  });

  it("selects the active option on Enter", async () => {
    const { user, onSelect, input } = setup();

    await user.type(input, "os");
    await screen.findAllByRole("option");
    await user.keyboard("{ArrowDown}{Enter}");

    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect).toHaveBeenCalledWith("opt-oslo");
    expect(input).toHaveValue("Oslo");
    expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
  });

  it("closes on Escape without selecting", async () => {
    const { user, onSelect, input } = setup();

    await user.type(input, "os");
    await screen.findAllByRole("option");
    await user.keyboard("{Escape}");

    expect(onSelect).not.toHaveBeenCalled();
    expect(screen.queryByRole("listbox")).not.toBeInTheDocument();
  });

  it("resets the active option when the filter changes", async () => {
    const { user, input } = setup();

    await user.type(input, "o");
    await screen.findAllByRole("option");
    await user.keyboard("{ArrowDown}{ArrowDown}");
    await user.type(input, "s");

    // Without the reset, index 1 of the new list is an entry the user never
    // looked at - and Enter would select it.
    const options = await screen.findAllByRole("option");
    expect(input).toHaveAttribute("aria-activedescendant", options[0].id);
  });
