import { describe, expect, it } from "vitest";
import { PriceTag } from "./price-tag";

export const LOST: string[] = [
  "\"renders correctly\" encoded nothing: a whole-DOM snapshot fails on every change including intended ones, so its failure carries no information and the ritual response is to update it unread.",
  "\"renders sale correctly\" encoded one real requirement - that a sale shows the previous price as well as the current one - expressed as a class name, which is invisible to anyone not looking at the stylesheet.",
  "\"has the right test ids\" encoded nothing: it asserted that a developer-facing attribute existed, which no user can perceive and which any refactor may rename.",
