// v3rc07_profiling_perf / ex1 - reference solution.
import { Profiler } from "react";
import type { ProfilerOnRenderCallback, ReactElement, ReactNode } from "react";

export type RenderSample = {
  id: string;
  phase: "mount" | "update" | "nested-update";
  actualDuration: number;
  baseDuration: number;
  savedRatio: number;
};

export function Measured({
  id,
  onSample,
  children,
}: {
  id: string;
  onSample: (sample: RenderSample) => void;
  children: ReactNode;
}): ReactElement {
  // Fires once per commit, at commit time. Collecting samples from a render
  // body instead would double them under StrictMode's development double
  // invocation and send you hunting for a render loop that is not there.
  const handleRender: ProfilerOnRenderCallback = (
    profilerId,
    phase,
    actualDuration,
    baseDuration
  ) => {
    onSample({
      id: profilerId,
      phase,
      actualDuration,
      baseDuration,
      // baseDuration estimates the cost with no memoisation at all, and
      // actualDuration counts skipped components as zero - so this ratio is
      // the memoisation's report card. Near 0 means nothing is being skipped.
      savedRatio: baseDuration > 0 ? 1 - actualDuration / baseDuration : 0,
    });
  };

  return (
    <Profiler id={id} onRender={handleRender}>
      {children}
    </Profiler>
  );
}

export function summarise(samples: RenderSample[]) {
  let mounts = 0;
  let updates = 0;
  let totalActual = 0;
  let worst: RenderSample | null = null;

  for (const sample of samples) {
    // nested-update is a commit caused by a state update inside a layout
    // effect from an earlier commit in the same tick. For counting, it is an
    // update.
    if (sample.phase === "mount") mounts += 1;
    else updates += 1;

    totalActual += sample.actualDuration;
    if (!worst || sample.actualDuration > worst.actualDuration) worst = sample;
  }

  // Explicitly null for an empty array rather than reducing without an initial
  // value, which throws.
  return { mounts, updates, totalActual, worst };
}

