```

references.solution.tsx:
// v3rc07_profiling_perf / ex4 - reference solution.
import { createContext, useContext, useMemo, useState } from "react";
import type { ReactElement, ReactNode } from "react";

// Split by rate of change. Context has no selector: every consumer re-renders
// whenever the provider's value changes by Object.is, whatever it reads and
// whether or not it is wrapped in memo.
const UserContext = createContext<{ name: string } | null>(null);
const ThemeContext = createContext<"light" | "dark" | null>(null);
const QueryContext = createContext<string | null>(null);
// The setter lives alone, so a component that dispatches but never reads the
// query is not subscribed to it and does not re-render on a keystroke.
const SetQueryContext = createContext<((next: string) => void) | null>(null);

function required<T>(value: T | null, hook: string): T {
  if (value === null) throw new Error(`${hook}() must be used inside <AppProvider>`);
  return value;
}

export function useUser() {
  return required(useContext(UserContext), "useUser");
}
export function useTheme() {
  return required(useContext(ThemeContext), "useTheme");
}
export function useQuery() {
  return required(useContext(QueryContext), "useQuery");
}
export function useSetQuery() {
  return required(useContext(SetQueryContext), "useSetQuery");
}

export function AppProvider({
  user,
  theme,
  children,
}: {
  user: { name: string };
  theme: "light" | "dark";
  children: ReactNode;
}): ReactElement {
  const [query, setQuery] = useState("");

  // Still memoised: this fixes the other half of the problem, where a provider
  // re-render hands consumers a fresh but equivalent object. Splitting fixes
  // the half where the value genuinely changed.
  const userValue = useMemo(() => user, [user.name]);

  return (
    <UserContext value={userValue}>
      <ThemeContext value={theme}>
        {/* setQuery from useState is already stable, so this provider's value
            never changes and its consumers never re-render. */}
        <SetQueryContext value={setQuery}>
          <QueryContext value={query}>{children}</QueryContext>
        </SetQueryContext>
      </ThemeContext>
    </UserContext>
  );
}

