references.solution.tsx:
// v3rc07_profiling_perf / ex6 - reference solution.
import { memo, useDeferredValue, useMemo, useState } from "react";
import type { ReactElement } from "react";

type Item = { id: string; label: string };

const ResultList = memo(function ResultList({
  items,
  query,
  onRender,
}: {
  items: Item[];
  query: string;
  onRender: () => void;
}): ReactElement {
  onRender();
  const matches = useMemo(
    () => items.filter((item) => item.label.toLowerCase().includes(query.toLowerCase())),
    [items, query]
  );
  return (
    <ul>
      {matches.map((item) => (
        <li key={item.id}>{item.label}</li>
      ))}
    </ul>
  );
});

function SearchInput({
  value,
  onChange,
  onRender,
}: {
  value: string;
  onChange: (next: string) => void;
  onRender: () => void;
}): ReactElement {
  onRender();
  return (
    <input
      type="search"
      aria-label="Search"
      value={value}
      onChange={(event) => onChange(event.target.value)}
    />
  );
}

export function SearchScreen({
  items,
  onInputRender,
  onListRender,
}: {
  items: Item[];
  onInputRender: () => void;
  onListRender: () => void;
}): ReactElement {
  const [query, setQuery] = useState("");
  // Holds the previous value while React renders the new one at low priority.
  // Unlike a debounce, the work has already started by the time the user
  // pauses - so the two delays do not add.
  const deferred = useDeferredValue(query);
  // The documented way to build a pending indication for this hook.
  const stale = query !== deferred;

  return (
    <div>
      <SearchInput value={query} onChange={setQuery} onRender={onInputRender} />
      <div data-stale={stale} style={{ opacity: stale ? 0.6 : 1 }}>
        {/* memo is load-bearing: without it the list re-renders on every
            parent render regardless of the deferral, and the expensive work
            happens anyway. */}
        <ResultList items={items} query={deferred} onRender={onListRender} />
      </div>
    </div>
  );
}

