## Exercise 7 — a transition, not a debounce

Edit `ex7/solution.tsx`. An expensive tab switch that stays responsive.

Export:

```tsx
export function TabbedReport(props: {
  tabs: { id: string; label: string; render: () => ReactNode }[];
  onPanelRender?: (id: string) => void;
}): ReactElement;
```

Requirements:

- a tablist of buttons with `role="tab"` and correct `aria-selected`, per the
  accessibility sector;
- clicking a tab marks it selected **immediately** — the `aria-selected`
  attribute must be correct in the very next commit, before the expensive panel
  has rendered;
- the panel's render happens in a transition, so a user clicking three tabs
  quickly does not wait for the first two to finish rendering;
- while a transition is pending, the tablist carries `aria-busy="true"` and the
  outgoing panel remains visible — not a spinner, not a blank;
- `onPanelRender` fires once per panel that actually rendered;
- also export `const WHY_NOT_DEBOUNCE: string`, one sentence saying what a
  300ms debounce on the tab click would do to the user experience.

The gate clicks three tabs in one synchronous burst and asserts the third tab's
`aria-selected` became `true` immediately, that `onPanelRender` fired for the
third tab, and that it fired at most twice in total.

```
uv run dojo test react v3rc07_profiling_perf ex7
```

references.solution.tsx:
// v3rc07_profiling_perf / ex7 - reference solution.
import { useState, useTransition } from "react";
import type { ReactElement, ReactNode } from "react";

export const WHY_NOT_DEBOUNCE: string =
  "A 300ms debounce would delay the tab even looking selected and would still take the full render time afterwards, so it adds latency and removes feedback while saving work the user was always going to need - debouncing is for work that leaves the process, like a request, which cannot be abandoned once started.";

type Tab = { id: string; label: string; render: () => ReactNode };

export function TabbedReport({
  tabs,
  onPanelRender,
}: {
  tabs: Tab[];
  onPanelRender?: (id: string) => void;
}): ReactElement {
  const [isPending, startTransition] = useTransition();
  // Two pieces of state on purpose: during a transition the selected tab and
  // the rendered panel genuinely differ, and that difference is the feature.
  const [selected, setSelected] = useState(tabs[0]?.id ?? "");
  const [panelId, setPanelId] = useState(tabs[0]?.id ?? "");

  function pick(id: string) {
    // Urgent: direct feedback on a click, committed in the very next render.
    setSelected(id);
    // Interruptible: React abandons this render if another tab is clicked
    // before it finishes, so three fast clicks do not render three panels.
    startTransition(() => setPanelId(id));
  }

  const panel = tabs.find((tab) => tab.id === panelId);

  return (
    <div>
      <div role="tablist" aria-busy={isPending || undefined}>
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={tab.id === selected}
            onClick={() => pick(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* The outgoing panel stays visible because panelId has not changed yet.
          A spinner here would replace information with less information, which
          is what transitions exist to avoid. */}
      <div role="tabpanel" style={{ opacity: isPending ? 0.6 : 1 }}>
        {panel && <Panel tab={panel} onRender={onPanelRender} />}
      </div>
    </div>
  );
}

function Panel({
  tab,
  onRender,
}: {
  tab: Tab;
  onRender?: (id: string) => void;
}): ReactElement {
  onRender?.(tab.id);
  return <>{tab.render()}</>;
}

