// v3rc07_profiling_perf / challenge - reference solution.
import {
  Suspense,
  createContext,
  memo,
  useContext,
  useDeferredValue,
  useMemo,
  useState,
  use,
} from "react";
import type { ReactElement, ReactNode } from "react";
import { VirtualList } from "./virtual-list";

type User = { id: string; name: string };
type Row = { id: string; label: string };
type DashboardApi = {
  fetchRevenue: () => Promise<number>;
  fetchVisits: () => Promise<number>;
  fetchSignups: () => Promise<number>;
  fetchRows: () => Promise<Row[]>;
};

// --- fix 1: split the context by rate of change (ex4) ---------------------
const UserContext = createContext<User | null>(null);
const ThemeContext = createContext<"light" | "dark">("light");

// --- fix 3: one round trip's worth of latency (ex5) -----------------------
async function loadSummary(api: DashboardApi) {
  // All three start now; none depends on another. A rejection is caught where
  // the promise is created, so one failure degrades one figure rather than
  // blanking the panel.
  const revenue = api.fetchRevenue().catch(() => null);
  const visits = api.fetchVisits().catch(() => null);
  const signups = api.fetchSignups().catch(() => null);
  return {
    revenue: await revenue,
    visits: await visits,
    signups: await signups,
  };
}

const Sidebar = memo(function Sidebar({ onRender }: { onRender: () => void }): ReactElement {
  onRender();
  const user = useContext(UserContext);
  const theme = useContext(ThemeContext);
  // Reads only rarely-changing contexts, so a keystroke never reaches it.
  return <aside data-theme={theme}>{user?.name}</aside>;
});

function SummaryBody({
  promise,
  onRender,
}: {
  promise: Promise<{ revenue: number | null; visits: number | null; signups: number | null }>;
  onRender: () => void;
}): ReactElement {
  onRender();
  const summary = use(promise);
  return (
    <dl>
      <dt>Revenue</dt>
      <dd>{summary.revenue ?? "—"}</dd>
      <dt>Visits</dt>
      <dd>{summary.visits ?? "—"}</dd>
      <dt>Signups</dt>
      <dd>{summary.signups ?? "—"}</dd>
    </dl>
  );
}

// --- fix 2: bounded DOM (ex8) plus a responsive input (ex6) ---------------
const ActivityTable = memo(function ActivityTable({
  rows,
  query,
  onRowRender,
}: {
  rows: Row[];
  query: string;
  onRowRender: (index: number) => void;
}): ReactElement {
  const matches = useMemo(
    () => rows.filter((row) => row.label.toLowerCase().includes(query.toLowerCase())),
    [rows, query]
  );

  return (
    <VirtualList
      items={matches}
      rowHeight={20}
      height={400}
      renderRow={(row: Row, index: number) => {
        onRowRender(index);
        return <span>{row.label}</span>;
      }}
    />
  );
});

export function Dashboard({
  api,
  user,
  theme,
  probes,
}: {
  api: DashboardApi;
  user: User;
  theme: "light" | "dark";
  probes: {
    onSidebarRender: () => void;
    onSummaryRender: () => void;
    onRowRender: (index: number) => void;
  };
}): ReactElement {
  const [query, setQuery] = useState("");
  // Windowing bounds the committed DOM; deferring keeps the input responsive.
  // Neither substitutes for the other.
  const deferredQuery = useDeferredValue(query);

  const summaryPromise = useMemo(() => loadSummary(api), [api]);
  const rowsPromise = useMemo(() => api.fetchRows(), [api]);
  const rows = use(rowsPromise);

  return (
    <UserContext value={user}>
      <ThemeContext value={theme}>
        <input
          type="search"
          aria-label="Filter activity"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
        />

        <Sidebar onRender={probes.onSidebarRender} />

        {/* One boundary, one loading state, instead of three staggered ones. */}
        <Suspense fallback={<p role="status">Loading summary</p>}>
          <SummaryBody promise={summaryPromise} onRender={probes.onSummaryRender} />
        </Suspense>

        <ActivityTable
          rows={rows}
          query={deferredQuery}
          onRowRender={probes.onRowRender}
        />
      </ThemeContext>
    </UserContext>
  );
}

