references.solution.tsx:
// v3rc07_profiling_perf / review1 - reference solution.
import { useState, useTransition } from "react";
import type { ReactElement, ReactNode } from "react";

export type Trace = {
  id: string;
  interaction: string;
  commits: number;
  totalActualMs: number;
  worstCommitMs: number;
  baseVsActual: number;
  committedNodes: number;
  networkRequests: { start: number; end: number }[];
};

export type Verdict =
  | { action: "none"; because: string }
  | { action: "transition"; because: string }
  | { action: "parallelise"; because: string }
  | { action: "window"; because: string };

function isStaircase(requests: { start: number; end: number }[]): boolean {
  if (requests.length < 2) return false;
  // Each request starting just after the previous one ended is a dependency
  // chain. It uses almost no CPU, so it is invisible in a flamegraph - the
  // network panel is the instrument for this one.
  return requests
    .slice(1)
    .every((request, index) => request.start >= requests[index].end - 20);
}

export function verdict(trace: Trace): Verdict {
  // Most specific first: D has both many commits and many nodes, and the node
  // count is the real story.
  if (trace.committedNodes > 10_000) {
    return {
      action: "window",
      because: `${trace.committedNodes} committed nodes means every subsequent style recalculation, layout and accessibility-tree update walks all of them - a permanent cost, not a one-off render cost.`,
    };
  }

  if (isStaircase(trace.networkRequests)) {
    return {
      action: "parallelise",
      because: `${trace.networkRequests.length} requests each starting when the previous finished is a dependency chain; total CPU is only ${trace.totalActualMs}ms, so this is latency, not work.`,
    };
  }

  if (trace.worstCommitMs > 200 && trace.worstCommitMs / trace.totalActualMs > 0.8) {
    return {
      action: "transition",
      because: `A single ${trace.worstCommitMs}ms commit accounts for nearly all the time, so the click blocks on one render - marking it interruptible lets the UI respond immediately.`,
    };
  }

  return {
    action: "none",
    because: `${trace.commits} commits totalling ${trace.totalActualMs}ms is below the threshold of perception; baseVsActual of ${trace.baseVsActual} says nothing is being skipped, and it does not matter. Memoising here buys nothing and adds a dependency array that can go stale.`,
  };
}

// The fix for trace B, implemented: the expensive panel render moves into a
// transition so the tab responds on the click that caused it.
export function ReportTabs({
  tabs,
}: {
  tabs: { id: string; label: string; render: () => ReactNode }[];
}): ReactElement {
  const [isPending, startTransition] = useTransition();
  const [selected, setSelected] = useState(tabs[0]?.id ?? "");
  const [shown, setShown] = useState(tabs[0]?.id ?? "");

  return (
    <div>
      <div role="tablist" aria-busy={isPending || undefined}>
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={tab.id === selected}
            onClick={() => {
              setSelected(tab.id);
              startTransition(() => setShown(tab.id));
            }}
          >
            {tab.label}
          </button>
        ))}
      </div>
      <div role="tabpanel" style={{ opacity: isPending ? 0.6 : 1 }}>
        {tabs.find((tab) => tab.id === shown)?.render()}
      </div>
    </div>
  );
}

