// v3rc08_design_systems_theming / ex2 - reference solution.
import type { ReactElement, ReactNode } from "react";

// Tier 1: named for what they ARE.
export const primitives = {
  blue600: "#2563eb",
  blue700: "#1d4ed8",
  red600: "#dc2626",
  slate50: "#f8fafc",
  slate200: "#e2e8f0",
  slate900: "#0f172a",
  white: "#ffffff",
};

// Tier 2: named for what they are FOR. This is the tier that survives a
// rebrand and the tier that makes dark mode possible.
export type SemanticToken =
  | "--color-accent"
  | "--color-accent-hover"
  | "--color-danger"
  | "--color-surface"
  | "--color-surface-raised"
  | "--color-text"
  | "--color-text-muted";

// Record<SemanticToken, string> on both stops them drifting: adding a token to
// the union without adding it to both objects is a compile error, whereas a
// dark theme missing one key just renders wrong and nobody notices.
export const lightTheme: Record<SemanticToken, string> = {
  "--color-accent": primitives.blue600,
  "--color-accent-hover": primitives.blue700,
  "--color-danger": primitives.red600,
  "--color-surface": primitives.slate50,
  "--color-surface-raised": primitives.white,
  "--color-text": primitives.slate900,
  "--color-text-muted": primitives.slate200,
};

// The same names, different primitives. Nothing downstream changes.
export const darkTheme: Record<SemanticToken, string> = {
  "--color-accent": primitives.blue600,
  "--color-accent-hover": primitives.blue700,
  "--color-danger": primitives.red600,
  "--color-surface": primitives.slate900,
  "--color-surface-raised": "#1e293b",
  "--color-text": primitives.slate50,
  "--color-text-muted": primitives.slate200,
};

// The whole rebrand: one call, two tokens.
export function rebrand(next: { accent: string; accentHover: string }) {
  const patch = {
    "--color-accent": next.accent,
    "--color-accent-hover": next.accentHover,
  } as const;
  return {
    light: { ...lightTheme, ...patch },
    dark: { ...darkTheme, ...patch },
  };
}

export function Notice({
  tone,
  title,
  children,
}: {
  tone: "info" | "danger";
  title: string;
  children: ReactNode;
}): ReactElement {
  return (
    <section
      style={{
        // Semantic tokens only. This component does not know what colour the
        // accent is, which is precisely what lets it survive a rebrand.
        background: "var(--color-surface-raised)",
        color: "var(--color-text)",
        borderLeft: `4px solid ${
          tone === "danger" ? "var(--color-danger)" : "var(--color-accent)"
        }`,
      }}
    >
      <h3>{title}</h3>
      <div>{children}</div>
    </section>
  );
}

