references.solution.tsx:
// v3rc08_design_systems_theming / ex3 - reference solution.
import type { CSSProperties, ReactElement, ReactNode } from "react";
import { darkTheme, lightTheme } from "./tokens";

export function ThemeScope({
  theme,
  children,
}: {
  theme: "light" | "dark";
  children: ReactNode;
}): ReactElement {
  const tokens = theme === "dark" ? darkTheme : lightTheme;

  return (
    <div
      data-theme={theme}
      style={
        {
          ...tokens,
          // Tells the browser which theme its OWN UI should use: scrollbars,
          // form controls, the default canvas. The most commonly missed line
          // in a dark mode implementation.
          colorScheme: theme,
          // CSSProperties does not officially allow arbitrary --* keys; cast
          // once, here, rather than at every call site.
        } as CSSProperties
      }
    >
      {children}
    </div>
  );
}

export function Panel({
  title,
  onRender,
  children,
}: {
  title: string;
  onRender?: () => void;
  children: ReactNode;
}): ReactElement {
  onRender?.();

  // No theme prop, no context, no knowledge that themes exist. Nesting works
  // because custom properties inherit and the nearest ancestor wins - which is
  // CSS doing the work, with no code here for it at all.
  return (
    <section
      style={{
        background: "var(--color-surface-raised)",
        color: "var(--color-text)",
        border: "1px solid var(--color-accent)",
      }}
    >
      <h3>{title}</h3>
      {children}
    </section>
  );
}

// A theme change re-renders NOTHING below the element whose attribute changed:
// React is not involved, the browser simply recomputes the styles of everything
// inheriting the changed custom properties.

