references.solution.tsx:
// v3rc08_design_systems_theming / ex4 - reference solution.
import { createContext, memo, useContext, useMemo } from "react";
import type { ReactElement, ReactNode } from "react";

export type Theme = { surface: string; text: string; accent: string };

const ThemeContext = createContext<Theme | null>(null);

export function useJsTheme(): Theme {
  const theme = useContext(ThemeContext);
  if (!theme) throw new Error("useJsTheme() must be used inside <JsThemeProvider>");
  return theme;
}

export function JsThemeProvider({
  theme,
  children,
}: {
  theme: Theme;
  children: ReactNode;
}): ReactElement {
  // Memoised on the fields, so an unrelated parent render does not hand
  // consumers a fresh but equivalent object. Built properly on purpose - a
  // sabotaged comparison would prove nothing.
  const value = useMemo(
    () => theme,
    [theme.surface, theme.text, theme.accent]
  );
  return <ThemeContext value={value}>{children}</ThemeContext>;
}

// memo does NOT save this component, and that is the lesson rather than a bug.
// memo compares props; a context-driven render is not caused by props, so every
// consumer re-renders whenever the provider's value changes.
export const JsPanel = memo(function JsPanel({
  title,
  onRender,
  children,
}: {
  title: string;
  onRender: () => void;
  children: ReactNode;
}): ReactElement {
  onRender();
  const theme = useJsTheme();
  return (
    <section style={{ background: theme.surface, color: theme.text, borderColor: theme.accent }}>
      <h3>{title}</h3>
      {children}
    </section>
  );
});

export const TRADEOFFS: string[] = [
  "Every consumer re-renders on a theme change, however memoised, because context has no selector and memo does not stop a context-driven render.",
  "The values are invisible to any CSS you did not write in JavaScript: pseudo-elements, ::selection, scrollbars, @media print and third-party stylesheets are all unthemed.",
  "Theming is coupled to React, so a theme change cannot happen before hydration - which is where the flash of wrong theme comes from.",
  "Nesting a sub-theme requires another provider and another subscription, where custom properties get it from CSS inheritance with no code at all.",
];

