export type VariantProps<V extends Record<string, Record<string, string>>> =
  Partial<{ [K in keyof V]: keyof V[K] }>;

export function variants<V extends Record<string, Record<string, string>>>(
  config: VariantConfig<V>
): (props?: VariantProps<V> & { className?: string }) => string;
```

Requirements, with the exact expected output:

```tsx
const button = variants({
  base: "btn",
  variants: {
    intent: { primary: "btn--primary", ghost: "btn--ghost" },
    size: { sm: "btn--sm", lg: "btn--lg" },
  },
  compoundVariants: [{ intent: "ghost", size: "lg", class: "btn--ghost-lg" }],
  defaultVariants: { intent: "primary", size: "sm" },
});

button();                              // "btn btn--primary btn--sm"
button({ intent: "ghost" });           // "btn btn--ghost btn--sm"
button({ intent: "ghost", size: "lg" });
// "btn btn--ghost btn--lg btn--ghost-lg"
button({ size: "lg", className: "mt-4" });
// "btn btn--primary btn--lg mt-4"
```

Order is part of the contract: base, then variants in config key order, then
matching compound variants in array order, then `className`. An unknown variant
name or value must be a **type error**. A variant explicitly set to `undefined`
falls back to its default.

```
