```

references.solution.tsx:
// v3rc08_design_systems_theming / ex5 - reference solution.
type VariantMap = Record<string, Record<string, string>>;

// "For each variant name, the allowed values are the keys of its map." One
// expression, reused for props, defaults and compound matchers.
export type VariantProps<V extends VariantMap> = Partial<{
  [K in keyof V]: keyof V[K];
}>;

export type VariantConfig<V extends VariantMap> = {
  base?: string;
  variants: V;
  compoundVariants?: (VariantProps<V> & { class: string })[];
  defaultVariants?: VariantProps<V>;
};

export function variants<V extends VariantMap>(config: VariantConfig<V>) {
  const { base, variants: map, compoundVariants = [], defaultVariants = {} } = config;

  return (props?: VariantProps<V> & { className?: string }): string => {
    const classes: string[] = [];
    if (base) classes.push(base);

    // Resolved values: an explicit undefined falls back to the default, which
    // is what `??` gives and `||` would not for an empty-string variant.
    const resolved = {} as Record<string, string | undefined>;
    // Object.keys is insertion order for string keys, which is what makes
    // "config key order" a stable, documentable contract.
    for (const name of Object.keys(map)) {
      const value = (props?.[name] ?? defaultVariants[name]) as string | undefined;
      resolved[name] = value;
      if (value !== undefined) {
        const className = map[name][value];
        if (className) classes.push(className);
      }
    }

    // Matched against the RESOLVED values, not the passed ones - so a compound
    // variant fires when one half came from a default.
    for (const compound of compoundVariants) {
      const { class: compoundClass, ...matchers } = compound;
      const matches = Object.entries(matchers).every(
        ([name, value]) => resolved[name] === value
      );
      if (matches) classes.push(compoundClass);
    }

    if (props?.className) classes.push(props.className);

    return classes.join(" ");
  };
}

