```

references.solution.tsx:
// v3rc08_design_systems_theming / ex6 - reference solution.
import type { ReactElement } from "react";

export function cx(...values: (string | false | null | undefined)[]): string {
  return values.filter((value): value is string => Boolean(value)).join(" ");
}

export function Chip({
  label,
  selected,
  disabled,
  onToggle,
  className,
}: {
  label: string;
  selected: boolean;
  disabled?: boolean;
  onToggle: () => void;
  className?: string;
}): ReactElement {
  return (
    <button
      type="button"
      // The class attribute describes what this IS and never changes with
      // state. CSS selects state from the attributes below:
      //   .chip[data-selected="true"] { ... }
      //   .chip[data-disabled] { ... }
      // Base first, caller's classes after: replacing the base breaks every
      // chip that passes a className, and putting the base last means the
      // caller can never win a same-specificity conflict.
      className={cx("chip", className)}
      // A two-state value: present in both states so both are selectable.
      data-selected={selected}
      // A flag: `undefined` removes the attribute, whereas `false` would
      // render the string "false" and match a bare [data-disabled] selector.
      data-disabled={disabled || undefined}
      // ARIA as well as data, because these two states have accessible
      // meanings. Where a state has an ARIA equivalent, prefer it and style
      // from it; reserve data-* for states with no accessible meaning.
      aria-pressed={selected}
      aria-disabled={disabled || undefined}
      onClick={() => {
        // aria-disabled does not stop anything happening, so the handler must.
        if (disabled) return;
        onToggle();
      }}
    >
      {label}
    </button>
  );
}

