## Exercise 7 — dark mode without the flash

Edit `ex7/solution.tsx`. System preference, explicit override, persistence, and
no white flash.

Export:

```tsx
export type ThemeChoice = "light" | "dark" | "system";

export const THEME_BOOT_SCRIPT: string;

export function useSystemTheme(): "light" | "dark";
export function useThemeChoice(): {
  choice: ThemeChoice;
  resolved: "light" | "dark";
  setChoice: (next: ThemeChoice) => void;
};

export function ThemeToggle(): ReactElement;
```

Requirements:

- `THEME_BOOT_SCRIPT` is a string of JavaScript intended for an inline
  `<script>` in `<head>`: it reads `localStorage.getItem("theme")`, falls back
  to `matchMedia("(prefers-color-scheme: dark)")`, and sets both
  `documentElement.dataset.theme` and `documentElement.style.colorScheme`. It
  must be wrapped in a try/catch, because `localStorage` throws in some
  privacy modes;
- `useSystemTheme` subscribes to the media query with `useSyncExternalStore` —
  the same shape as the reduced-motion hook — and returns `"light"` during
  server rendering;
- `useThemeChoice` reads the persisted choice, resolves `"system"` against the
  live system value, writes the choice to `localStorage`, and applies
  `data-theme` and `colorScheme` to `documentElement` whenever `resolved`
  changes;
- `ThemeToggle` is a three-option radio group labelled `Theme` with options
  `Light`, `Dark`, `System`;
- changing the OS preference while `choice` is `"system"` must update the page
  live.

The gate installs a fake `matchMedia` and `localStorage`, runs
`THEME_BOOT_SCRIPT` against a stub document and asserts the attribute is set,
then mounts the toggle, dispatches a media change, and asserts the resolved
theme followed.

```
uv run dojo test react v3rc08_design_systems_theming ex7
```

references.solution.tsx:
// v3rc08_design_systems_theming / ex7 - reference solution.
import { useCallback, useEffect, useState, useSyncExternalStore } from "react";
import type { ReactElement } from "react";

export type ThemeChoice = "light" | "dark" | "system";

const STORAGE_KEY = "theme";
const QUERY = "(prefers-color-scheme: dark)";

// Inline in <head>, deliberately blocking. Nothing written in a component runs
// early enough: the browser paints before the bundle has even loaded, so the
// user sees the wrong theme first. A few hundred inline bytes is a good trade.
export const THEME_BOOT_SCRIPT = `try{
  var stored = localStorage.getItem(${JSON.stringify(STORAGE_KEY)});
  var dark = stored === "dark" || (stored !== "light" && window.matchMedia(${JSON.stringify(QUERY)}).matches);
  document.documentElement.dataset.theme = dark ? "dark" : "light";
  document.documentElement.style.colorScheme = dark ? "dark" : "light";
}catch(e){}`;
// The try/catch is not padding: localStorage THROWS on access in some privacy
// modes, and an uncaught error here leaves the page unthemed entirely.

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

export function useSystemTheme(): "light" | "dark" {
  return useSyncExternalStore(
    subscribe,
    // A string snapshot, stable by Object.is when nothing changed. An object
    // here would loop.
    () => (window.matchMedia(QUERY).matches ? "dark" : "light"),
    () => "light"
  );
}

function readChoice(): ThemeChoice {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored === "light" || stored === "dark" ? stored : "system";
  } catch {
    return "system";
  }
}

export function useThemeChoice() {
  const [choice, setChoiceState] = useState<ThemeChoice>(readChoice);
  const system = useSystemTheme();
  // Persisting the CHOICE, not the resolved value: storing "dark" when the
  // user picked "system" on a dark machine means their preference stops
  // following the system tomorrow morning.
  const resolved: "light" | "dark" = choice === "system" ? system : choice;

  const setChoice = useCallback((next: ThemeChoice) => {
    setChoiceState(next);
    try {
      if (next === "system") localStorage.removeItem(STORAGE_KEY);
      else localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* privacy mode; the in-memory choice still applies for this session */
    }
  }, []);

  useEffect(() => {
    document.documentElement.dataset.theme = resolved;
    document.documentElement.style.colorScheme = resolved;
  }, [resolved]);

  return { choice, resolved, setChoice };
}

export function ThemeToggle(): ReactElement {
  const { choice, setChoice } = useThemeChoice();
  const options: ThemeChoice[] = ["light", "dark", "system"];

  return (
    <fieldset>
      <legend>Theme</legend>
      {options.map((option) => (
        <label key={option}>
          <input
            type="radio"
            name="theme"
            value={option}
            checked={choice === option}
            onChange={() => setChoice(option)}
          />
          {option[0].toUpperCase() + option.slice(1)}
        </label>
      ))}
    </fieldset>
  );
}

