references.solution.tsx:
// v3rc08_design_systems_theming / ex8 - reference solution.
import type { ReactElement, ReactNode } from "react";
import type { SpaceStep } from "./tokens";

// container-type on an ancestor is required. Without it, @container silently
// matches nothing - no error, no warning, just a layout that never switches.
// The host wrapper exists because an element cannot query itself: containment
// applies to the container, so the queried element must be an ancestor.
export const CARD_CSS = `
.card-host { container-type: inline-size; }

.card {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-3);
}

@container (min-width: 400px) {
  .card { grid-template-columns: 120px 1fr; }
}
`;

export function Stack({
  gap = 3,
  as = "div",
  children,
}: {
  gap?: SpaceStep;
  as?: "div" | "ul" | "section";
  children: ReactNode;
}): ReactElement {
  const Component = as;
  return (
    <Component
      style={{
        display: "flex",
        flexDirection: "column",
        // gap, never margins: margins collapse, leak outside the component,
        // and always need a :last-child special case.
        gap: `var(--space-${gap})`,
        margin: 0,
        padding: 0,
      }}
    >
      {children}
    </Component>
  );
}

export function Cluster({
  gap = 2,
  align = "center",
  children,
}: {
  gap?: SpaceStep;
  align?: "start" | "center" | "baseline";
  children: ReactNode;
}): ReactElement {
  return (
    <div
      style={{
        display: "flex",
        flexWrap: "wrap",
        alignItems: align === "start" ? "flex-start" : align,
        gap: `var(--space-${gap})`,
      }}
    >
      {children}
    </div>
  );
}

export function MediaCard({
  title,
  summary,
  imageSrc,
  actions,
}: {
  title: string;
  summary: string;
  imageSrc: string;
  actions?: ReactNode;
}): ReactElement {
  return (
    <div className="card-host">
      <div className="card">
        <img src={imageSrc} alt="" />
        {/* No margins anywhere in this component: outer spacing is a statement
            about sibling relationships, which is the parent's business. */}
        <Stack gap={2}>
          <h3>{title}</h3>
          <p>{summary}</p>
          {actions != null && <Cluster gap={2}>{actions}</Cluster>}
        </Stack>
      </div>
    </div>
  );
}

