```

references.solution.tsx:
// v3rc08_design_systems_theming / challenge - reference solution.
import type {
  ComponentPropsWithoutRef,
  ElementType,
  MouseEvent,
  ReactElement,
  ReactNode,
} from "react";
import { variants } from "./variants";
import { cx } from "./cx";

// Layers, not specificity. Without them the component's rule and a consumer's
// rule sit at equal specificity and the bundler's emit order decides - which
// works locally and breaks in production.
export const BUTTON_CSS = `
/* Consumers: put your overrides in the \`overrides\` layer. A rule there beats
   anything in \`components\` regardless of specificity or source order. */
@layer components, overrides;

@layer components {
  .btn {
    /* Two-level lookup: a consumer can set --button-bg on any ancestor and
       restyle the button without writing a rule that must win a cascade
       fight at all. */
    background: var(--button-bg, var(--color-accent));
    color: var(--button-fg, var(--color-surface));
    padding-inline: var(--button-padding-x, var(--space-3));
    padding-block: var(--button-padding-y, var(--space-2));
    border-radius: var(--button-radius, var(--radius-2));
    border: 1px solid transparent;
  }

  .btn--secondary { --button-bg: transparent; --button-fg: var(--color-text); }
  .btn--danger    { --button-bg: var(--color-danger); }
  .btn--sm { --button-padding-x: var(--space-2); --button-padding-y: var(--space-1); }
  .btn--lg { --button-padding-x: var(--space-4); --button-padding-y: var(--space-3); }
  .btn--danger-lg { --button-bg: var(--color-danger); border-color: var(--color-danger); }

  .btn[data-loading="true"] { cursor: progress; }
  .btn__slot { display: inline-flex; min-width: 1em; justify-content: center; }
}
`;

const button = variants({
  base: "btn",
  variants: {
    intent: {
      primary: "btn--primary",
      secondary: "btn--secondary",
      danger: "btn--danger",
    },
    size: { sm: "btn--sm", md: "btn--md", lg: "btn--lg" },
  },
  // A fact about the combination: no class on `danger` or on `lg` alone can
  // express it.
  compoundVariants: [{ intent: "danger", size: "lg", class: "btn--danger-lg" }],
  defaultVariants: { intent: "primary", size: "md" },
});

type ButtonOwnProps = {
  intent?: "primary" | "secondary" | "danger";
  size?: "sm" | "md" | "lg";
  loading?: boolean;
  startSlot?: ReactNode;
  endSlot?: ReactNode;
  className?: string;
  children: ReactNode;
};

export function Button<T extends ElementType = "button">({
  as,
  intent,
  size,
  loading = false,
  startSlot,
  endSlot,
  className,
  children,
  ...rest
}: { as?: T } & ButtonOwnProps &
  Omit<ComponentPropsWithoutRef<T>, keyof ButtonOwnProps | "as">): ReactElement {
  const Component = (as ?? "button") as ElementType;

  const callerOnClick = (rest as { onClick?: (event: MouseEvent) => void }).onClick;

  return (
    <Component
      {...rest}
      {...(Component === "button" ? { type: "button" as const } : null)}
      // Classes describe what it IS; state lives in attributes, so the class
      // attribute never changes and never invalidates a consumer's selector.
      className={cx(button({ intent, size }), className)}
      data-loading={loading}
      aria-busy={loading || undefined}
      // aria-disabled, not disabled: a disabled button loses focus the instant
      // it becomes disabled, throwing a keyboard user to the top of the
      // document mid-submit.
      aria-disabled={loading || undefined}
      onClick={(event: MouseEvent) => {
        if (loading) {
          event.preventDefault();
          return;
        }
        callerOnClick?.(event);
      }}
    >
      {/* The spinner replaces the start slot's contents rather than being
          added beside it, so the button's geometry does not change and nothing
          after it shifts under the user's cursor. */}
      {(startSlot != null || loading) && (
        <span className="btn__slot" aria-hidden="true">
          {loading ? <span className="btn__spinner" /> : startSlot}
        </span>
      )}
      {children}
      {endSlot != null && (
        <span className="btn__slot" aria-hidden="true">
          {endSlot}
        </span>
      )}
    </Component>
  );
}

// v3rc08_design_systems_theming / review1 - reference solution.
import type { ReactElement } from "react";
import { Stack } from "./primitives";

export const MIGRATION_NOTES: string[] = [
  "The original had two different internal gaps (8px after the heading, 12px after the blurb). A single Stack cannot express both, so the card now uses two nested Stacks: gap 2 (8px) around the heading and blurb, gap 3 (12px) before the price. Geometry is preserved exactly.",
  "marginBottom: 24 was removed rather than tokenised. Outer spacing is a statement about sibling relationships and belongs to the parent; callers now wrap cards in <Stack gap={5}>, which is the same 24px.",
  "#64748b (muted text) had no exact semantic token, so --color-text-muted was added to both themes rather than reaching for the nearest existing token - approximating a colour that appears in every card would have been visible.",
  "borderRadius: 6 is not on the radius scale, which has 4 and 8. It was mapped to --radius-2 (6px), added to the scale, because rounding to 4 or 8 was a visible change and this component is not the only one using 6.",
];

export function PriceCard({
  name,
  blurb,
  price,
}: {
  name: string;
  blurb: string;
  price: string;
}): ReactElement {
  return (
    <div
      style={{
        // Every colour is now a meaning rather than a value, which is what
        // makes dark mode possible at all - the hex literals made it
        // impossible for this component no matter what the rest of the app did.
        background: "var(--color-surface-raised)",
        color: "var(--color-text)",
        border: "1px solid var(--color-border)",
        borderRadius: "var(--radius-2)",
        padding: "var(--space-4)",
        // No marginBottom: outer spacing is the parent's job. Callers wrap in
        // <Stack gap={5}> for the original 24px.
      }}
    >
