          <h3 style={{ fontSize: "var(--font-size-3)", margin: 0 }}>{name}</h3>
          <p
            style={{
              color: "var(--color-text-muted)",
              fontSize: "var(--font-size-1)",
              margin: 0,
            }}
          >
            {blurb}
          </p>
        </Stack>
        <strong
          style={{ color: "var(--color-accent)", fontSize: "var(--font-size-5)" }}
        >
          {price}
        </strong>
      </Stack>
    </div>
  );
}
